QCU_T("es", "biomecanique", {
  "0": ["La estática se define como el estudio:",["De los cuerpos sometidos a fuerzas sin movimiento","De los cuerpos en movimiento uniformemente acelerado","De los cuerpos deformables sometidos a tensiones"],["La estática estudia los cuerpos sometidos a fuerzas en ausencia de movimiento, por oposición a la dinámica.","Los cuerpos en movimiento corresponden a la dinámica.","Los cuerpos deformables corresponden a la mecánica de materiales, no a la estática de los cuerpos rígidos."]],
  "1": ["La cinemática estudia el movimiento:",["Teniendo en cuenta las fuerzas aplicadas","Sin tener en cuenta las fuerzas que lo producen","Únicamente en el plano sagital del cuerpo"],["Tener en cuenta las fuerzas es lo que define la cinética.","La cinemática describe la geometría del movimiento; es la cinética la que relaciona movimiento y fuerzas.","La cinemática no se limita a ningún plano en particular."]],
  "2": ["Una magnitud escalar se caracteriza por:",["Una dirección y un sentido","Un origen y una línea de acción","Una magnitud únicamente"],["La dirección y el sentido caracterizan a las magnitudes vectoriales.","El origen y la línea de acción son elementos del vector.","Una magnitud escalar se define por un número y su unidad: no tiene ni dirección ni sentido."]],
  "3": ["El centro de masas de un cuerpo corresponde:",["Al punto en el que la masa queda equitativamente repartida","Siempre al centro geométrico del cuerpo","Al punto de aplicación de la fuerza de reacción del suelo"],["El centro de masas es el punto único en el que se anula la suma de las posiciones relativas ponderadas de la masa distribuida.","El reparto desigual de la masa desplaza ese punto respecto al centro geométrico.","Ese punto es el centro de presiones."]],
  "4": ["El centro de presiones (COP) corresponde:",["Al centro de masas del conjunto del cuerpo del sujeto","Al punto de aplicación de la resultante de las fuerzas en el suelo","A la proyección vertical del centro de gravedad en el suelo"],["El centro de masas es una propiedad del reparto de la masa, no del apoyo.","El centro de presiones es el punto en el que se concentra la fuerza total que actúa sobre la persona.","La proyección del centro de gravedad no coincide necesariamente con el centro de presiones."]],
  "5": ["En el adulto, el centro de gravedad se sitúa aproximadamente:",["Al 45 % de la talla del sujeto de pie","Al 70 % de la talla del sujeto de pie","Entre el 55 y el 57 % de la talla"],["Ese valor es inferior al que establece el temario.","El setenta y dos por ciento corresponde al niño de un año, no al adulto.","En el plano horizontal, el centro de gravedad se sitúa al 57 % de la talla en el hombre y al 55 % en la mujer."]],
  "6": ["Un equilibrio se considera estable cuando:",["El centro de rotación está por encima del centro de gravedad","El centro de gravedad permanece en el mismo lugar tras una perturbación","El centro de rotación está por debajo del centro de gravedad"],["El temario define el equilibrio estable como un péndulo cuyo centro de rotación está por encima del centro de gravedad: tras aplicar una fuerza, el cuerpo recupera siempre su posición inicial.","Un centro de gravedad que no se desplaza caracteriza más bien el equilibrio neutro.","Un centro de rotación situado por debajo del centro de gravedad da un equilibrio inestable."]],
  "7": ["Un factor que aumenta la estabilidad es:",["Una base de sustentación más estrecha","Una base de sustentación amplia","Un centro de gravedad situado más alto"],["Una base estrecha reduce, al contrario, la estabilidad.","Ampliar la base de sustentación aumenta la superficie sobre la que el centro de gravedad puede desplazarse sin romper el equilibrio.","Un centro de gravedad alto disminuye la estabilidad."]],
  "8": ["La base de sustentación corresponde:",["A la superficie corporal total del sujeto apoyada en el suelo","A la proyección vertical del centro de masas sobre el suelo de apoyo","A la superficie delimitada por los puntos de contacto con el suelo"],["La superficie corporal total no interviene en el equilibrio.","La proyección del centro de masas es un punto, no una superficie.","La base de sustentación es la zona delimitada por los puntos de contacto del cuerpo con el suelo, sobre la que debe proyectarse el centro de gravedad."]],
  "9": ["La antropometría estudia:",["Las dimensiones y proporciones del cuerpo humano","Las fuerzas internas musculares","Los movimientos articulares en dinámica"],["La antropometría mide las dimensiones y las proporciones corporales, que se emplean para estimar las masas segmentarias.","Las fuerzas musculares corresponden a la cinética.","Los movimientos articulares corresponden a la cinemática."]],
  "10": ["La postura estática se define como:",["Un control neuromuscular en movimiento","Una posición del cuerpo respecto al espacio","Una reacción adaptativa a una perturbación"],["El control neuromuscular en movimiento define la postura dinámica.","El temario contrapone la postura estática, posición del cuerpo en el espacio, a la postura dinámica, que corresponde al control neuromuscular.","Las reacciones posturales son respuestas, no la definición de la postura estática."]],
  "11": ["Un vector se define por:",["Una magnitud expresada en su unidad","Una unidad de medida y una dirección","Una magnitud, una dirección y un sentido"],["La magnitud por sí sola define una cantidad escalar.","La unidad no basta para caracterizar un vector.","El vector se define por su módulo, su dirección y su sentido, a los que se añade su punto de aplicación."]],
  "12": ["El origen de un vector corresponde:",["A su punto de aplicación, allí donde se ejerce la fuerza","A su punto de llegada, en el extremo de la flecha","A su dirección en el espacio de referencia"],["El origen del vector es su punto de aplicación, allí donde se ejerce la fuerza.","El punto de llegada es el extremo del vector, no su origen.","La dirección la determina la línea de acción."]],
  "13": ["En un sistema de coordenadas de mano derecha:",["Los ejes son independientes entre sí en el espacio","Los ejes respetan una orientación tridimensional convencional","Los ejes siguen la regla de la mano izquierda, en sentido inverso"],["Los ejes están ligados por una convención de orientación.","El sistema de mano derecha fija por convención la orientación relativa de los tres ejes del espacio.","La regla de la mano izquierda da el sistema opuesto."]],
  "14": ["La cinética estudia:",["Solo la geometría del movimiento","Los desplazamientos, sin las fuerzas","La relación entre movimiento y fuerzas"],["La descripción geométrica del movimiento corresponde a la cinemática.","El estudio de los desplazamientos por sí solos corresponde también a la cinemática.","La cinética relaciona el movimiento con las fuerzas que lo producen, mientras que la cinemática solo describe su geometría."]],
  "15": ["Una fuerza interna es:",["Una fuerza muscular producida por el individuo","Una fuerza producida por la atracción de la gravedad","Una fuerza de reacción ejercida por el suelo"],["Las fuerzas internas las genera el propio organismo, y la primera de ellas es la fuerza muscular.","La gravedad es una fuerza externa.","La reacción del suelo es una fuerza externa."]],
  "16": ["Una fuerza externa gravitatoria:",["La produce la contracción del músculo","Se debe a la atracción terrestre","Depende únicamente del punto de apoyo en el suelo"],["La contracción muscular produce una fuerza interna.","La fuerza gravitatoria es una fuerza externa que resulta de la atracción que ejerce la Tierra sobre la masa del cuerpo.","El punto de apoyo condiciona la palanca, no el origen de la gravedad."]],
  "17": ["Un sistema de fuerzas simultáneas significa que:",["Las fuerzas actúan sobre dos segmentos distintos","Las fuerzas aplicadas son todas paralelas","Las fuerzas actúan en el mismo instante"],["El segmento de aplicación no define la simultaneidad.","El paralelismo caracteriza un sistema de fuerzas paralelas, no simultáneas.","Las fuerzas simultáneas se ejercen en el mismo momento sobre el cuerpo considerado."]],
  "18": ["El par (momento de fuerza) corresponde:",["Al efecto de rotación de una fuerza","Al efecto de traslación que produce una fuerza","A la suma de todas las fuerzas aplicadas"],["El momento de fuerza es el efecto de una fuerza en un movimiento de rotación.","El efecto de traslación corresponde a la fuerza en sí.","La suma de las fuerzas da la resultante, no el momento."]],
  "19": ["La fórmula del momento de fuerza es:",["M = F / r","M = r × F","M = r + F"],["El momento es un producto, no un cociente.","El momento es el producto vectorial del brazo de palanca por la fuerza: su módulo es el brazo de palanca multiplicado por la fuerza y por el seno del ángulo que forman.","El momento no es una suma de dos magnitudes de naturaleza distinta."]],
  "20": ["El brazo de palanca corresponde:",["A la distancia que separa la fuerza de la carga que hay que desplazar en el suelo","A la longitud total del segmento óseo que moviliza el músculo agonista","A la distancia perpendicular entre la línea de acción de la fuerza y el eje"],["La distancia entre la fuerza y la carga no define el brazo de palanca.","La longitud del hueso no es el brazo de palanca.","El brazo de palanca es la distancia perpendicular que separa la línea de acción de la fuerza del eje de rotación."]],
  "21": ["Un momento es máximo cuando:",["El ángulo entre r y F es de 90°","El ángulo entre r y F es nulo","La fuerza es paralela al segmento"],["El módulo del momento contiene el seno del ángulo que forman: es máximo con un ángulo recto.","Un ángulo nulo anula el seno y, por tanto, el momento.","Una fuerza paralela al segmento no produce ninguna rotación."]],
  "22": ["Un diagrama de cuerpo libre sirve para:",["Representar únicamente los músculos activos durante el movimiento","Representar todas las fuerzas aplicadas a un cuerpo","Visualizar los movimientos articulares del segmento estudiado"],["La representación no se limita a las fuerzas musculares.","El diagrama de cuerpo libre aísla el segmento estudiado y representa el conjunto de las fuerzas que se le aplican.","La visualización del movimiento corresponde al análisis cinemático."]],
  "23": ["En cadena cinética abierta:",["El segmento distal está fijado a un apoyo","El segmento proximal está fijado a un apoyo","El segmento distal está móvil"],["Un segmento distal fijo define la cadena cinética cerrada.","La distinción se refiere al segmento distal, no al proximal.","En cadena cinética abierta el segmento distal queda libre para desplazarse, mientras que en cadena cerrada está fijado."]],
  "24": ["Una palanca de primer género se caracteriza por:",["Un punto de apoyo entre la fuerza y la resistencia","Una resistencia situada entre la fuerza y el punto de apoyo","Una fuerza entre la resistencia y el apoyo"],["En la palanca de primer género, el eje se sitúa entre el esfuerzo muscular y la resistencia.","La resistencia en el medio caracteriza la palanca de segundo género.","El esfuerzo en el medio caracteriza la palanca de tercer género."]],
  "25": ["Una palanca de segundo género presenta:",["Una ventaja mecánica estrictamente inferior a 1","Una ventaja mecánica superior a 1","Siempre una producción de velocidad importante"],["Una ventaja inferior a 1 caracteriza la palanca de tercer género.","Al estar la resistencia más cerca del eje que el esfuerzo, la relación entre los brazos es superior a 1 y el sistema resulta ventajoso en fuerza.","La producción de velocidad caracteriza la palanca de tercer género."]],
  "26": ["Las palancas de tercer género se utilizan principalmente para:",["Desplazar cargas pesadas con un esfuerzo reducido","Aumentar la estabilidad global de la articulación","Producir velocidad y amplitud"],["El desplazamiento de cargas pesadas conviene a la palanca de segundo género.","La estabilidad no depende del género de la palanca.","El esfuerzo se aplica cerca del eje: la fuerza queda en desventaja, pero la velocidad y la amplitud del segmento distal se amplifican."]],
  "27": ["En el cuerpo humano, las palancas más frecuentes son:",["Las palancas de tercer género","Las palancas de primer género","Las palancas de segundo género"],["La mayoría de las inserciones musculares se sitúan cerca de la articulación, lo que privilegia la velocidad y la amplitud.","La palanca de primer género existe en el cuerpo, pero es minoritaria.","La palanca de segundo género es la más infrecuente en el cuerpo humano."]],
  "28": ["El equilibrio se alcanza cuando:",["La suma de las fuerzas es nula únicamente","La suma de las fuerzas y de los momentos es nula","La suma de los momentos es nula únicamente"],["Unas fuerzas equilibradas pueden producir todavía una rotación.","El equilibrio exige a la vez una resultante de fuerzas nula y una suma de momentos nula.","Unos momentos equilibrados no impiden una traslación."]],
  "29": ["Un aumento de la masa corporal:",["Disminuye siempre la estabilidad, sea cual sea la base","No influye en absoluto en la estabilidad del sujeto en apoyo","Puede aumentar la estabilidad si la base es suficiente"],["El efecto de la masa depende de la base de sustentación.","La masa sí interviene en el equilibrio.","Una masa mayor aumenta la estabilidad siempre que la base de sustentación siga siendo adecuada."]],
  "30": ["La fricción interviene en la estabilidad porque:",["Impide el desplazamiento relativo de las superficies","Aumenta la altura del centro de gravedad","Reduce la base de sustentación del sujeto en apoyo"],["El rozamiento se opone al deslizamiento entre el cuerpo y su apoyo, condición necesaria para mantener el equilibrio.","El rozamiento no actúa sobre la altura del centro de gravedad.","El rozamiento no modifica la extensión de la base de sustentación."]],
  "31": ["El feedforward corresponde:",["A una respuesta posterior al movimiento","A una anticipación motora","A una corrección sensorial"],["Una respuesta posterior al movimiento corresponde al feedback.","El feedforward es la vertiente anticipatoria del control postural, que prepara la actividad muscular antes de la perturbación.","La corrección basada en las aferencias corresponde al feedback."]],
  "32": ["El feedback es:",["Una anticipación motora preparada de origen central","Un programa motor automático, estereotipado y preestablecido","Una corrección basada en la información sensorial"],["La anticipación central define el feedforward.","Un programa automático no supone ninguna corrección sensorial.","El feedback corrige el movimiento a partir de la información aferente visual, vestibular y somatosensorial."]],
  "33": ["El sistema vestibular informa principalmente sobre:",["La orientación de la cabeza y el equilibrio","La visión periférica y el campo visual","La posición articular fina de los segmentos"],["El sistema vestibular es una de las tres entradas del control postural, junto con la visual y la somatosensorial; informa sobre la orientación de la cabeza.","La visión periférica corresponde al sistema visual.","La posición articular corresponde al sistema somatosensorial."]],
  "34": ["Un movimiento de traslación se caracteriza por:",["Una rotación del segmento alrededor de un eje fijo","Puntos con trayectorias paralelas","Puntos con trayectorias diferentes"],["La rotación alrededor de un eje define el movimiento de rotación.","En una traslación, todos los puntos del cuerpo describen trayectorias paralelas y recorren la misma distancia.","Las trayectorias diferentes se dan en la rotación."]],
  "35": ["Un movimiento de rotación implica:",["Una velocidad lineal idéntica para todos los puntos del segmento","Una aceleración nula en todos los puntos del segmento en rotación","Una velocidad lineal distinta según la distancia al eje"],["Una velocidad lineal común caracteriza la traslación.","La rotación se acompaña de una aceleración centrípeta.","En rotación, la velocidad lineal de un punto crece a medida que se aleja del eje, mientras que la velocidad angular es común."]],
  "36": ["Un movimiento rectilíneo uniforme significa:",["Una aceleración nula","Una aceleración constante","Una aceleración variable"],["El movimiento rectilíneo uniforme se produce a velocidad constante en dirección y en módulo: la aceleración es nula, conforme a la ley de inercia.","Una aceleración constante no nula define el movimiento uniformemente acelerado.","Una aceleración variable corresponde a un movimiento no uniformemente acelerado."]],
  "37": ["La caída libre es un ejemplo de:",["Movimiento rectilíneo uniforme, a velocidad constante","Movimiento rectilíneo uniformemente acelerado","Movimiento curvilíneo con aceleración variable"],["Un movimiento uniforme supondría una aceleración nula.","En caída libre, la aceleración de la gravedad es constante: el movimiento es rectilíneo y uniformemente acelerado.","La trayectoria de la caída libre vertical es rectilínea."]],
  "38": ["El principio de acción-reacción establece que:",["Toda fuerza aplicada produce necesariamente un movimiento","Toda fuerza es proporcional a la masa del cuerpo","A toda acción corresponde una reacción igual y opuesta"],["Una fuerza puede estar equilibrada y no producir ningún movimiento.","La proporcionalidad a la masa corresponde a la ley de la aceleración.","La ley de acción-reacción enuncia que dos cuerpos en interacción ejercen entre sí fuerzas del mismo módulo y de sentidos opuestos."]],
  "39": ["El principio del momento de fuerza es fundamental para:",["El análisis de las palancas y de las articulaciones","El análisis de la postura estática en bipedestación","El estudio de la velocidad angular de los segmentos"],["El principio del momento de fuerza fundamenta el análisis de los sistemas de palancas que constituyen las articulaciones.","La postura estática corresponde al principio de equilibrio.","La velocidad angular es una magnitud cinemática."]],
  "40": ["¿Qué establece la primera ley de Newton?",["La aceleración es proporcional a la fuerza e inversamente proporcional a la masa","Todo cuerpo conserva su reposo o su movimiento uniforme si no actúa una fuerza desequilibrada","Toda acción provoca una reacción igual y opuesta, del mismo módulo"],["Ese enunciado es el de la ley fundamental de la dinámica.","La ley de inercia enuncia que un cuerpo mantiene su estado de reposo o de movimiento uniforme mientras no actúe sobre él ninguna fuerza desequilibrada.","Ese enunciado es el de la tercera ley."]],
  "41": ["¿Cómo se denomina la primera ley de Newton?",["La ley fundamental","La ley de acción-reacción","La ley de inercia de los cuerpos"],["Ese es el nombre de la segunda ley.","Ese es el nombre de la tercera ley.","La primera ley de Newton es la ley de inercia."]],
  "42": ["¿Qué establece la ley fundamental de la dinámica?",["La aceleración es proporcional a la fuerza e inversamente proporcional a la masa","Un cuerpo conserva su estado de reposo mientras no se ejerza ninguna fuerza desequilibrada","Dos cuerpos en interacción ejercen fuerzas opuestas y del mismo módulo"],["La segunda ley de Newton relaciona la aceleración de un objeto con la fuerza resultante que se ejerce sobre él y con su masa.","Ese enunciado es el de la ley de inercia.","Ese enunciado es el de la ley de acción-reacción."]],
  "43": ["¿Qué lugar ocupa la ley de acción-reacción entre las leyes de Newton?",["La primera","La tercera","La segunda"],["La primera ley es la ley de inercia.","La ley de la acción y la reacción es la tercera ley de Newton.","La segunda ley es la ley fundamental de la dinámica."]],
  "44": ["¿Qué enuncia el principio fuerza-movimiento?",["El tiempo de aplicación cuenta tanto como la magnitud de la fuerza","La fuerza que produce el músculo varía según la velocidad de su contracción","Actúan fuerzas desequilibradas sobre el cuerpo en cuanto se crea o se modifica un movimiento"],["Ese enunciado es el del principio fuerza-tiempo.","Ese enunciado es el del principio fuerza-velocidad.","Para crear o modificar un movimiento hace falta que se ejerzan fuerzas desequilibradas sobre el cuerpo."]],
  "45": ["¿Qué equilibra la gravedad en bipedestación estática?",["La fuerza de reacción del suelo bajo los pies","La fuerza muscular de los flexores plantares","La fuerza de inercia del segmento cabeza-brazos-tronco"],["En bipedestación estática, la fuerza de la gravedad queda equilibrada por la fuerza de reacción del suelo que se ejerce bajo los pies.","La fuerza muscular ajusta el equilibrio, pero no es la fuerza de oposición que se describe.","La inercia no interviene en situación estática."]],
  "46": ["¿Qué hay que producir para salir de la bipedestación estática?",["Una reducción de la fuerza de reacción que ejerce el suelo bajo los pies","Fuerzas horizontales y verticales mayores con las piernas","Un desplazamiento del centro de gravedad obtenido sin ninguna fuerza nueva"],["La fuerza de reacción aumenta en lugar de disminuir.","El inicio del movimiento exige generar con las piernas fuerzas horizontales y verticales superiores a las del equilibrio estático.","Un desplazamiento sin fuerza nueva es imposible."]],
  "47": ["¿Qué enuncia el principio fuerza-tiempo?",["La fuerza disminuye cuando aumenta la velocidad de acortamiento","Toda fuerza desequilibrada crea o modifica un movimiento","El tiempo de aplicación de la fuerza cuenta tanto como su magnitud"],["Ese enunciado es el de la relación fuerza-velocidad.","Ese enunciado es el del principio fuerza-movimiento.","El principio fuerza-tiempo enuncia que la duración de aplicación de una fuerza importa tanto como su intensidad."]],
  "48": ["¿Cuál es el interés de aplicar una fuerza durante más tiempo?",["Alcanzar una velocidad mayor gracias a un impulso más grande","Reducir la fuerza necesaria para obtener un mismo desplazamiento del cuerpo","Aumentar la masa que el movimiento moviliza realmente"],["Una fuerza aplicada durante más tiempo produce un impulso mayor y, por tanto, una variación de la cantidad de movimiento y una velocidad final superiores.","La reducción del esfuerzo no es el efecto que se describe.","La masa no se modifica por la duración de la aplicación."]],
  "49": ["¿Cómo varía la fuerza en una acción concéntrica rápida?",["Aumenta a medida que se eleva la velocidad de acortamiento","Disminuye a medida que aumenta la velocidad de acortamiento","Se mantiene constante, sea cual sea la velocidad de acortamiento"],["La evolución que se describe es la inversa.","La curva fuerza-velocidad muestra que la fuerza producida baja cuando se eleva la velocidad de acortamiento.","La fuerza sí varía con la velocidad."]],
  "50": ["¿Cómo varía la fuerza en una acción excéntrica?",["Disminuye a medida que aumenta la velocidad de alargamiento","Es independiente de la velocidad de alargamiento","Aumenta con la velocidad de alargamiento"],["Esa evolución es la del régimen concéntrico.","La velocidad sí influye en la fuerza en excéntrico.","La fuerza que el músculo puede soportar se eleva a medida que aumenta la velocidad de alargamiento."]],
  "51": ["¿Qué tipo de fibras permite una mayor velocidad de acortamiento?",["Las fibras rápidas","Las fibras lentas","Los dos tipos de fibras"],["Con el mismo número de sarcómeros, un músculo rico en fibras rápidas alcanza una velocidad de acortamiento superior.","Las fibras lentas producen una velocidad de acortamiento menor.","El tipo de fibra sí influye en la velocidad."]],
  "52": ["¿En qué consiste el ciclo de estiramiento-acortamiento?",["En una sucesión de contracciones isométricas mantenidas sin ninguna relajación","En un contramovimiento frenado en excéntrico, seguido de inmediato por una acción concéntrica","En un alargamiento lento seguido de un simple retorno pasivo de naturaleza elástica"],["La isometría no forma parte de este ciclo.","El ciclo asocia un contramovimiento ralentizado por una acción excéntrica, seguido inmediatamente por una acción concéntrica en la dirección buscada.","El retorno que se describe es activo, no pasivo."]],
  "53": ["¿A qué condición potencia la fuerza el ciclo de estiramiento-acortamiento?",["Si el contramovimiento es lo más lento posible","Si la acción excéntrica se sustituye por una isometría","Si el intervalo entre las dos acciones musculares es mínimo"],["La lentitud del contramovimiento no es la condición que se describe.","El frenado excéntrico es indispensable en este ciclo.","La potenciación de la acción concéntrica exige un intervalo temporal mínimo después del frenado excéntrico."]],
  "54": ["¿Qué designa el término sinergia en control motor?",["Las reglas que permiten el uso coordinado de los músculos","La suma aritmética de todas las fuerzas musculares","La activación simultánea de un músculo y de su antagonista"],["La sinergia designa las reglas subyacentes del sistema neuromuscular que permiten utilizar los músculos de forma coordinada.","La sinergia no es una simple suma de fuerzas.","La cocontracción no es la definición establecida."]],
  "55": ["¿De qué depende el control motor?",["Únicamente de la orden cortical voluntaria","De los propioceptores y de los reflejos","Únicamente de la relación fuerza-velocidad del músculo"],["La orden voluntaria no basta para este control.","El control motor se basa en los propioceptores y en los reflejos que estos desencadenan.","La relación fuerza-velocidad es una propiedad mecánica, no un mecanismo de control."]],
  "56": ["¿En qué condición se desencadena un reflejo?",["Con la mínima estimulación del receptor","Únicamente bajo control voluntario consciente","Cuando el estímulo sensorial supera un determinado umbral"],["Hace falta superar un umbral para que aparezca el reflejo.","El reflejo es, por definición, involuntario.","Los reflejos solo se activan si el estímulo sensorial supera un umbral determinado."]],
  "57": ["¿A qué son sensibles los husos neuromusculares?",["Al estiramiento del cuerpo muscular","A la tensión del tendón","A la posición de la articulación"],["Los husos neuromusculares detectan el estiramiento y envían señales excitadoras que activan el músculo para protegerlo.","La tensión tendinosa la detecta el órgano tendinoso de Golgi.","La posición articular corresponde a otros receptores."]],
  "58": ["¿Qué reflejo desencadenan los husos neuromusculares con su señal excitadora?",["El reflejo miotático inverso, a través de los órganos de Golgi","El reflejo miotático y la inhibición recíproca","El reflejo de retirada nociceptivo, a través de los nociceptores"],["El reflejo miotático inverso está ligado a la respuesta a los estiramientos rápidos.","La excitación procedente de los husos corresponde al reflejo miotático, acompañado de la inhibición recíproca del antagonista.","La retirada nociceptiva no se describe aquí."]],
  "59": ["¿Cómo responden los husos neuromusculares según la velocidad de estiramiento?",["Reaccionan con más intensidad a los estiramientos lentos","Responden igual, sea cual sea la velocidad","Reaccionan con más intensidad a los estiramientos rápidos"],["La respuesta es más marcada ante los estiramientos rápidos.","La velocidad modifica claramente la intensidad de la respuesta.","Sensibles al estiramiento lento, los husos responden con mucha más intensidad a los estiramientos rápidos."]],
  "60": ["¿De qué depende la propiocepción?",["De los órganos sensoriales y del sistema vestibular","Únicamente del sistema visual y de la visión periférica","Únicamente de la relación fuerza-tiempo del músculo activado"],["La propiocepción se basa en los órganos sensoriales y en el sistema vestibular.","La visión contribuye al equilibrio, pero no define la propiocepción.","La relación fuerza-tiempo es una propiedad mecánica."]],
  "61": ["¿Qué característica distingue a la palanca de segundo género?",["El brazo de palanca de la fuerza es siempre menor que el de la carga","El brazo de palanca de la fuerza es siempre mayor que el de la carga","Los dos brazos de palanca tienen necesariamente la misma longitud"],["Esa situación caracteriza a la palanca de tercer género.","En la palanca de segundo género, el brazo del esfuerzo siempre supera al de la carga, de donde resulta una ventaja mecánica superior a 1.","La igualdad de los brazos no es la característica que se describe."]],
  "62": ["¿Qué ventaja mecánica caracteriza a la palanca de tercer género?",["Una ventaja mecánica estrictamente superior a 1","Una ventaja mecánica siempre exactamente igual a 1","Una ventaja mecánica inferior a 1"],["Una ventaja superior a 1 caracteriza a la palanca de segundo género.","La igualdad no es la característica que se describe.","Al aplicarse el esfuerzo más cerca del eje que la carga, la ventaja mecánica es inferior a 1: es la palanca más extendida en el cuerpo humano."]],
  "63": ["El ciclo de marcha se define como la secuencia comprendida entre:",["Dos contactos sucesivos del mismo pie con el suelo","Dos contactos sucesivos de pies opuestos","El contacto del talón y el despegue del antepié"],["El ciclo de marcha es la secuencia de los componentes que se producen entre dos contactos sucesivos del mismo pie con el suelo.","El contacto de dos pies opuestos delimita un paso, no un ciclo completo.","Ese intervalo solo cubre la fase de apoyo."]],
  "64": ["¿Qué proporción del ciclo de marcha representa la fase de apoyo?",["Alrededor del 40 %","Alrededor del 60 %","Alrededor del 50 %"],["El cuarenta por ciento corresponde a la fase de oscilación.","La fase de apoyo, durante la cual el pie está en contacto con el suelo, ocupa alrededor del 60 % del ciclo.","Las dos fases no se reparten el ciclo a partes iguales."]],
  "65": ["¿Qué ocurre durante la fase de oscilación?",["El pie se apoya por completo en el suelo","Los dos pies están simultáneamente en el suelo","El pie está suspendido y progresa hacia delante"],["El apoyo plantar completo pertenece a la fase de apoyo.","El doble apoyo pertenece a la fase de apoyo.","Durante la oscilación, que ocupa alrededor del 40 % del ciclo, el pie queda suspendido en el aire y se favorece su progresión."]],
  "66": ["¿Cómo se define la cadencia de marcha?",["El número de pasos por unidad de tiempo","La distancia recorrida por unidad de tiempo","La distancia entre dos apoyos sucesivos"],["La cadencia es el número de pasos por minuto; también se calcula a partir de la velocidad y de la longitud de la zancada.","La distancia por unidad de tiempo define la velocidad de marcha.","La distancia entre dos apoyos define la longitud del paso."]],
  "67": ["¿Cómo se define la longitud del paso?",["La distancia entre dos contactos sucesivos del talón del mismo pie","La distancia entre el contacto del talón de un miembro y el del miembro opuesto","La distancia que separa ambos talones, medida en el plano frontal"],["Esa distancia define la longitud de la zancada.","La longitud del paso separa el contacto del talón de un miembro del contacto del talón del miembro opuesto.","Esa distancia define la anchura del paso."]],
  "68": ["¿Cómo se define la longitud de la zancada?",["La distancia entre los contactos de talones opuestos con el suelo","La distancia recorrida en un minuto de marcha continua","La distancia entre dos choques sucesivos del talón del mismo pie"],["Esa distancia define la longitud del paso.","La distancia por unidad de tiempo define la velocidad.","La longitud de la zancada es la distancia lineal entre el contacto del talón de un pie y el siguiente choque del talón de ese mismo pie."]],
  "69": ["¿A qué corresponde la anchura del paso?",["A la distancia que separa ambos talones","A la distancia entre dos choques del mismo talón","Al ángulo que forma el pie con la línea de progresión"],["La anchura del paso, o anchura de la base, es la distancia entre ambos talones.","Esa distancia define la longitud de la zancada.","Ese ángulo es el ángulo del pie, un parámetro distinto."]],
  "70": ["¿Qué miden los parámetros cinemáticos de la marcha?",["Las fuerzas de reacción del suelo y los momentos articulares internos que se producen","Los desplazamientos, velocidades y aceleraciones, en particular los ángulos articulares","La duración del ciclo, el tiempo de apoyo y el tiempo de oscilación del miembro"],["Las fuerzas y los momentos corresponden al análisis cinético.","Los parámetros cinemáticos describen desplazamientos, velocidades y aceleraciones, en particular los ángulos de las articulaciones del miembro inferior.","Esas duraciones corresponden a los parámetros espaciotemporales."]],
  "71": ["¿Cuál es el objetivo biomecánico de la marcha humana?",["Maximizar la longitud de zancada alcanzada en cada paso","Mantener el centro de gravedad estrictamente inmóvil al caminar","Minimizar el desplazamiento vertical y lateral del centro de gravedad"],["El alargamiento del paso no es un fin en sí mismo.","Una inmovilidad absoluta es imposible durante la locomoción.","El objetivo es limitar los desplazamientos del centro de gravedad, para ahorrar la energía que se gasta."]],
  "72": ["¿En qué intercambio energético se basan los mecanismos de optimización de la marcha?",["La transformación de la energía potencial en energía cinética y a la inversa","La transformación de la energía química del músculo en energía térmica","El almacenamiento exclusivo de la energía elástica en los tendones del miembro"],["Los mecanismos de optimización transforman la energía potencial en energía cinética y a la inversa a lo largo del ciclo.","Esa conversión no describe el mecanismo de optimización mecánica.","El almacenamiento elástico no es el mecanismo establecido."]],
  "73": ["¿Cuál es el efecto de la rotación pélvica alrededor del eje vertical?",["Aumenta la anchura de la base de sustentación en el suelo durante el apoyo","Reduce el desplazamiento vertical del tronco para una longitud de paso dada","Reduce el desplazamiento lateral del centro de gravedad del cuerpo en apoyo monopodal"],["La rotación pélvica no amplía la base de apoyo.","La rotación pélvica permite, con el mismo desplazamiento vertical, alargar el paso, o reducir ese desplazamiento para un paso dado.","La reducción lateral se obtiene mediante el ángulo femorotibial."]],
  "74": ["¿Cuál es el efecto del descenso pélvico durante la marcha?",["Aumenta la longitud efectiva del miembro inferior que carga, en apoyo","Desciende el centro de masas del segmento cabeza-brazos-tronco","Reduce los movimientos verticales de la parte superior del cuerpo"],["El alargamiento efectivo del miembro procede del contacto del talón y del despegue del antepié.","No se describe ningún desplazamiento de ese tipo.","La caída pélvica disminuye las oscilaciones verticales de la parte superior del cuerpo, lo que aumenta la eficiencia energética de la marcha."]],
  "75": ["¿Por qué se flexiona la rodilla durante la fase de apoyo?",["Para reducir los movimientos verticales de la cadera, el tronco y la cabeza","Para aumentar la fuerza propulsora que desarrolla el tríceps sural","Para ampliar la base de sustentación durante la fase de doble apoyo"],["Cuando la cadera pasa por encima del pie, una cierta flexión de la rodilla baja la trayectoria y limita las oscilaciones verticales.","La propulsión corresponde al tercer rodillo.","La flexión de la rodilla no modifica la base de apoyo."]],
  "76": ["¿Cuál es el papel del ángulo femorotibial en la optimización de la marcha?",["Reduce el desplazamiento vertical del tronco durante la fase de apoyo","Reduce el desplazamiento del centro de gravedad en el plano horizontal","Aumenta la longitud de la zancada en cada paso"],["La reducción vertical se obtiene mediante la rotación y el descenso pélvicos.","El valgo fisiológico de la rodilla acerca los apoyos a la línea media y limita las oscilaciones laterales del centro de gravedad.","El ángulo femorotibial no alarga la zancada."]],
  "77": ["¿Cuál es el interés del contacto del talón y del despegue del antepié?",["Reducen la anchura del paso durante el doble apoyo","Aumentan la cadencia de marcha espontánea del sujeto","Aumentan la longitud efectiva del miembro inferior"],["Estos mecanismos no actúan sobre la anchura del paso.","La cadencia no depende de estos mecanismos.","Al prolongar el apoyo hacia atrás y después hacia delante, alargan funcionalmente el miembro y suavizan la trayectoria del centro de gravedad."]],
  "78": ["¿Qué designa el segmento HAT en el análisis de la marcha?",["La cabeza, los brazos y el tronco","La cadera, el tobillo y los dedos","La cadera, la rodilla y el tobillo"],["El segmento HAT reúne la cabeza, los brazos y el tronco, que se desplazan lo más rectos posible en la dirección del movimiento.","Esa combinación no corresponde al segmento descrito.","Esas articulaciones son los elementos motores, distintos del segmento HAT."]],
  "79": ["¿Dónde se sitúa el centro de masas del segmento cabeza-brazos-tronco?",["Exactamente al mismo nivel que el del cuerpo entero","Algo más arriba que el centro de gravedad del cuerpo entero","Claramente más abajo que el del cuerpo entero"],["Se describe una diferencia de altura entre ambos.","El centro de masas del segmento HAT se sitúa ligeramente por encima del centro de gravedad del conjunto del cuerpo.","Al ser el segmento HAT superior, su centro de masas está más alto."]],
  "80": ["¿A qué modelo mecánico se asimila el miembro inferior durante la marcha?",["A una palanca de primer género única y rígida","A un resorte elástico pasivo, sin control activo","A un doble péndulo controlado por la actividad muscular"],["El miembro no se reduce a una palanca única.","Un comportamiento puramente pasivo no daría cuenta del control muscular.","El miembro inferior se comporta como un doble péndulo cuyo movimiento controla la actividad muscular."]],
  "81": ["¿Sobre qué eje se desarrolla el primer rodillo de la marcha?",["Sobre el eje calcáneo","Sobre el eje tibioastragalino","Sobre el eje metatarsiano"],["El primer rodillo se produce sobre el talón, desde el contacto inicial hasta el apoyo de toda la planta del pie.","El eje del tobillo corresponde al segundo rodillo.","Esas articulaciones corresponden al tercer rodillo."]],
  "82": ["¿Qué músculo controla el primer rodillo de la marcha?",["El sóleo, en excéntrico","El tibial anterior, en excéntrico","El tríceps sural, en concéntrico"],["El sóleo controla el segundo rodillo.","El rodillo del talón lo frena la actividad excéntrica del tibial anterior, que controla el descenso del antepié.","El tríceps sural se encarga del tercer rodillo."]],
  "83": ["¿Qué ocurre durante el segundo rodillo de la marcha?",["El talón se despega y el peso pasa al antepié","El antepié descende hacia el suelo tras el contacto del talón","La planta del pie se apoya en el suelo y la tibia avanza"],["Esa transferencia corresponde al tercer rodillo.","Ese descenso corresponde al primer rodillo.","El segundo rodillo se produce sobre el eje del tobillo: la planta se apoya en el suelo mientras la tibia progresa hacia delante."]],
  "84": ["¿Qué músculo controla el segundo rodillo de la marcha?",["El sóleo, en excéntrico","El tibial anterior, en excéntrico","El tríceps sural, en concéntrico"],["El avance de la tibia sobre el pie fijado lo frena la acción excéntrica del sóleo.","El tibial anterior controla el primer rodillo.","El trabajo concéntrico del tríceps sural pertenece al tercer rodillo."]],
  "85": ["¿Qué músculo se encarga del tercer rodillo de la marcha?",["El sóleo, en excéntrico","El tríceps sural, en concéntrico","El tibial anterior, en concéntrico"],["El sóleo trabaja en excéntrico durante el segundo rodillo.","El rodillo del antepié lo produce la actividad concéntrica del tríceps sural, que propulsa el cuerpo hacia delante.","El tibial anterior no interviene en la propulsión."]],
  "86": ["¿Qué parte de la fuerza que se desarrolla durante la marcha representa el tercer rodillo?",["Alrededor del 60 %","Alrededor del 40 %","Alrededor del 85 %"],["El sesenta por ciento corresponde a la duración de la fase de apoyo.","El cuarenta por ciento corresponde a la duración de la fase de oscilación.","El tercer rodillo, el del antepié, representa el 85 % de la fuerza que se produce durante la marcha."]],
  "87": ["¿Cuál es la posición del tobillo en el contacto inicial?",["En posición neutra, a 0°","En flexión plantar de 10°","En flexión dorsal progresiva"],["En el contacto inicial el tobillo está neutro, la rodilla flexionada a 5° y la cadera flexionada a 30°.","La flexión plantar de 10° se produce en el apoyo inicial.","La flexión dorsal progresiva caracteriza el apoyo medio."]],
  "88": ["¿Cuál es la posición de la cadera en el contacto inicial?",["En extensión completa","En flexión de 30°","En posición neutra"],["La extensión de cadera se construye progresivamente durante el apoyo.","La cadera está flexionada unos 30° en el contacto inicial, posición que se repite en el apoyo terminal.","La cadera no está neutra en el momento del contacto del talón."]],
  "89": ["¿Cuál es la actividad de los flexores dorsales durante el apoyo inicial?",["Concéntrica","Isométrica","Excéntrica"],["El trabajo concéntrico de los flexores dorsales interviene durante la oscilación.","No se describe ninguna contracción isométrica en esta fase.","Los flexores dorsales frenan en excéntrico la flexión plantar de 10° que lleva la planta al suelo."]],
  "90": ["¿Cuándo empieza la fase de apoyo inicial?",["En el contacto inicial, hasta que el pie contralateral abandona el suelo","En el despegue del pie contralateral, hasta el despegue del talón","En el despegue del talón, hasta el contacto del pie opuesto"],["El apoyo inicial, o respuesta a la carga, empieza en el contacto inicial y se prolonga hasta el despegue del pie opuesto.","Ese intervalo define el apoyo medio.","Ese intervalo define el apoyo final."]],
  "91": ["¿Cuáles son los límites de la fase de apoyo medio?",["Del contacto inicial al despegue del pie contralateral","Del despegue del pie contralateral al despegue del talón homolateral","Del despegue del talón hasta el contacto del pie contralateral"],["Ese intervalo define el apoyo inicial.","El apoyo medio empieza cuando el pie opuesto abandona el suelo y termina cuando el talón del lado estudiado se eleva.","Ese intervalo define el apoyo final."]],
  "92": ["¿En qué porcentaje del ciclo se sitúa la fase de preoscilación?",["Entre el 30 y el 50 %","Entre el 60 y el 75 %","Entre el 50 y el 60 %"],["Ese tramo corresponde al apoyo terminal.","Ese tramo corresponde a la oscilación inicial.","La preoscilación, marcada por el despegue del antepié, ocupa el tramo del 50 al 60 % del ciclo."]],
  "93": ["¿Qué amplitud de flexión alcanza la rodilla durante la oscilación inicial?",["Alrededor de 60°","Alrededor de 30°","Alrededor de 15°"],["Durante la oscilación inicial, la rodilla se flexiona hasta unos 60° para permitir el paso del pie.","Treinta grados corresponde a la flexión de cadera, no de la rodilla.","De diez a quince grados corresponde a la flexión de la rodilla en el apoyo inicial."]],
  "94": ["¿Cómo se define un momento interno durante la marcha?",["Un momento que produce únicamente la fuerza de reacción que ejerce el suelo","Un momento que producen los músculos para contrarrestar el momento externo","Un momento que resulta únicamente de la inercia del segmento en oscilación"],["La fuerza de reacción del suelo genera el momento externo.","Los momentos internos los generan los músculos para oponerse a los momentos externos que crea la fuerza de reacción del suelo.","La inercia no define el momento interno."]],
  "95": ["¿Qué caracteriza a la marcha humana como modo de locomoción?",["Reduce el gasto energético al suprimir las oscilaciones","Se basa en un patrón de marcha rígido y poco adaptable","Libera los miembros superiores y amplía el campo visual"],["Las oscilaciones se limitan, no se suprimen.","El patrón de marcha es, al contrario, flexible y adaptable.","La locomoción bípeda permite una interacción más eficaz con el entorno al liberar los miembros superiores y ofrecer un campo visual más amplio."]],
  "96": ["¿Cuáles son las cuatro funciones del pie durante la marcha?",["Absorción de los impactos, estabilidad, progresión y contacto con el suelo","Propulsión, equilibrio, amortiguación y orientación del paso","Apoyo, suspensión, transmisión de las fuerzas y amortiguación"],["El pie se encarga de la absorción de los impactos, la estabilidad, la progresión mediante los rodillos y el contacto con el suelo.","La propulsión y el equilibrio no figuran como tales en la lista del temario.","La suspensión y la transmisión no figuran en la lista del temario."]],
  "97": ["¿Qué articulaciones se encargan de la absorción de los impactos en el pie?",["La talocrural y la tibioperonea distal de la pierna","Las metatarsofalángicas, la mediotarsiana y la subastragalina","Las interfalángicas y la tarsometatarsiana del pie"],["La talocrural se encarga de la progresión mediante el rodillo de tobillo, no de la amortiguación.","La absorción de los impactos corre a cargo de las metatarsofalángicas, la mediotarsiana y la subastragalina.","Esas dos articulaciones no figuran entre los amortiguadores que se citan."]],
  "98": ["¿Qué estructuras garantizan la estabilidad del pie?",["La eversión subastragalina y los peroneos","Los tres rodillos y el tendón de Aquiles","La inversión subastragalina y la fascia plantar"],["La eversión, al contrario, desbloquea el mediopié.","Los rodillos se encargan de la progresión, no de la estabilidad.","La estabilidad del pie se basa en la inversión subastragalina y en la fascia plantar."]],
  "99": ["¿Qué hace la metatarsofalángica durante el rodillo de talón?",["Se coloca en flexión dorsal y retrasa la caída del pie","Se coloca en flexión plantar máxima desde el contacto","Permanece estrictamente neutra hasta el apoyo completo"],["La dorsiflexión metatarsofalángica durante el rodillo de talón frena el descenso del pie.","La flexión plantar no es el movimiento que se describe en este momento.","La posición neutra solo se alcanza en la oscilación."]],
  "100": ["¿Cuándo alcanza la metatarsofalángica su máximo de flexión dorsal?",["Durante el contacto inicial, en cuanto el talón se apoya en el suelo","Durante la preoscilación, al final del rodillo del antepié","Durante la oscilación media, con el pie despegado"],["El contacto inicial corresponde al comienzo del rodillo de talón.","La dorsiflexión vuelve durante el rodillo del antepié y culmina en la preoscilación, antes del retorno a la posición neutra en la oscilación.","En la oscilación, la articulación vuelve a la posición neutra."]],
  "101": ["¿Qué ocurre con la bóveda plantar durante el rodillo de tobillo?",["Recupera su concavidad máxima","Permanece estrictamente igual","Alcanza su aplanamiento máximo"],["La recuperación de la bóveda se produce durante el rodillo del antepié.","La bóveda sí se modifica a lo largo del apoyo.","Ligeramente aplanada ya en el rodillo de talón, la bóveda alcanza su aplanamiento máximo en el rodillo de tobillo."]],
  "102": ["¿Qué rodillo permite recuperar la bóveda plantar?",["El rodillo del antepié","El rodillo de talón","El rodillo de tobillo"],["El rodillo del antepié sirve para recuperar la bóveda plantar aplanada durante el apoyo.","El rodillo de talón inicia, al contrario, el aplanamiento.","El rodillo de tobillo corresponde al aplanamiento máximo."]],
  "103": ["¿Qué articulación del pie presenta la mayor amplitud de movimiento?",["La mediotarsiana","La subastragalina","La metatarsofalángica"],["La mediotarsiana tiene una amplitud menor que la subastragalina.","La subastragalina es la articulación del pie que presenta la mayor cantidad de movimiento.","La metatarsofalángica tiene una amplitud menor que la subastragalina."]],
  "104": ["¿Cuál es la eversión subastragalina máxima durante la marcha normal?",["De 10 a 12°, alcanzada en torno al 14 % del ciclo","De 4 a 6°, alcanzada en torno al 52 % del ciclo","De 4 a 6°, alcanzada en torno al 14 % del ciclo"],["Esa amplitud es superior a la que se describe.","El cincuenta y dos por ciento corresponde al máximo de inversión.","La eversión alcanza su máximo de 4 a 6° alrededor del 14 % del ciclo de marcha."]],
  "105": ["¿En qué momento del ciclo alcanza la inversión subastragalina su máximo?",["En torno al 52 % del ciclo","En torno al 14 % del ciclo de marcha","En torno al 85 % del ciclo de marcha"],["La transición de la eversión a la inversión se produce en el apoyo final, y la inversión culmina en torno al 52 % del ciclo.","El catorce por ciento corresponde al máximo de eversión.","Ese porcentaje corresponde al inicio de la oscilación terminal."]],
  "106": ["¿Qué provoca una fuerza de reacción del suelo que pasa por fuera del eje subastragalino?",["Un varo del calcáneo y una rotación externa del astrágalo","Un valgo del calcáneo y una rotación interna del astrágalo","Un bloqueo inmediato de la movilidad del mediopié"],["Esos efectos corresponden a una fuerza que pasa por dentro del eje.","Una fuerza lateral al eje subastragalino provoca un valgo calcáneo, un desplazamiento medial y una rotación interna del astrágalo, que se transmite al miembro.","El bloqueo del mediopié resulta de la inversión."]],
  "107": ["¿Qué provoca una fuerza de reacción del suelo que pasa por dentro del eje subastragalino?",["Un valgo del calcáneo y una rotación interna del astrágalo","Una eversión máxima del calcáneo desde el contacto inicial","Un varo del calcáneo y una rotación externa del astrágalo"],["Esos efectos corresponden a una fuerza que pasa por fuera del eje.","La eversión máxima se produce al principio del apoyo.","Una fuerza medial al eje subastragalino provoca un varo calcáneo, un desplazamiento lateral y una rotación externa del astrágalo."]],
  "108": ["¿Qué ocurre con los planos astragaloescafoideo y calcaneocuboideo en eversión?",["Se vuelven paralelos y permiten la movilidad del mediopié","Divergen claramente y bloquean la movilidad del mediopié","Se superponen y suprimen toda movilidad del mediopié"],["En eversión, el paralelismo de ambos planos deja cierta movilidad de flexoextensión al mediopié durante el apoyo inicial.","La divergencia y el bloqueo corresponden a la inversión.","Esa descripción no corresponde a ninguno de los dos estados."]],
  "109": ["¿Cuál es el efecto de la inversión sobre la movilidad del mediopié?",["Vuelve los planos paralelos y libera la movilidad del mediopié","Hace divergir los planos y bloquea el mediopié en el apoyo final","No tiene efecto sobre la movilidad del mediopié en apoyo"],["El paralelismo y la movilidad corresponden a la eversión.","En inversión, la divergencia de los planos astragaloescafoideo y calcaneocuboideo bloquea el mediopié, condición de la rigidez necesaria para el despegue.","La inversión sí modifica la movilidad del mediopié."]],
  "110": ["¿Cómo se comporta el retropié en el contacto inicial?",["Va de entrada a una inversión máxima del calcáneo","Permanece estrictamente neutro hasta el apoyo medio del pie","Va a una ligera eversión, con fuerza de reacción lateral"],["La inversión máxima solo se produce en el apoyo final.","Ya en el contacto inicial se inicia una eversión.","En el contacto inicial se instaura una ligera eversión, ya que la fuerza de reacción es lateral al eje subastragalino."]],
  "111": ["¿Qué amplitud recorre la pelvis en los tres planos durante la marcha?",["Del orden de unos pocos grados solamente","Del orden de 30 a 40° por plano","Del orden de 60° en el plano sagital"],["Los desplazamientos pélvicos son de poca amplitud, del orden de 3 a 10° según el plano considerado.","Esa amplitud es muy superior a la de la pelvis.","Esa amplitud corresponde a la flexión de la rodilla en oscilación."]],
  "112": ["¿Qué músculo realiza la flexión pasiva del hombro durante la marcha?",["El deltoides posterior","El coracobraquial","El deltoides medio"],["El deltoides posterior participa en la extensión activa.","La flexión de hombro durante la marcha es pasiva y corre a cargo del coracobraquial.","El deltoides medio se encarga de la abducción activa."]],
  "113": ["¿Qué músculos realizan la extensión activa del hombro durante la marcha?",["El coracobraquial, el deltoides anterior y el pectoral mayor","El deltoides medio, el supraespinoso y el trapecio superior","El deltoides posterior, el redondo mayor y el dorsal ancho"],["Estos músculos participan en la flexión, que es pasiva.","Estos músculos se encargan de la abducción.","La extensión del brazo durante la marcha es activa y corre a cargo del deltoides posterior, el redondo mayor y el dorsal ancho."]],
  "114": ["¿Cómo se comportan la cabeza y el tronco durante la marcha?",["Como una unidad funcional","Como dos segmentos independientes","Como un segmento fijo e inmóvil"],["El temario trata la cabeza y el tronco como una sola unidad, a la que se añade el sacro para los desplazamientos vertical y lateral.","Se describen, al contrario, como un conjunto solidario.","Los desplazamientos de esta unidad se describen, al contrario, con precisión."]],
  "115": ["¿Cuál es la amplitud del desplazamiento vertical de la cabeza y el tronco?",["De 10 a 12 cm, siguiendo un único trayecto sinusoidal","De 4,5 a 5 cm, siguiendo un doble trayecto sinusoidal","De 4,5 cm, siguiendo un único trayecto sinusoidal"],["Esa amplitud es muy superior a la que se describe.","El desplazamiento vertical sigue un doble trayecto sinusoidal de 4,5 a 5 cm por ciclo.","El trayecto sinusoidal único de 4,5 cm corresponde al desplazamiento lateral."]],
  "116": ["¿Dónde se sitúan los dos mínimos del desplazamiento vertical del tronco?",["En apoyo monopodal","Únicamente en el contacto inicial","En apoyo bipodal"],["El apoyo monopodal corresponde a los dos máximos.","El contacto inicial no constituye por sí solo un mínimo aislado.","El desplazamiento vertical pasa por dos mínimos en apoyo bipodal y dos máximos en apoyo monopodal."]],
  "117": ["¿Cuál es la característica del desplazamiento lateral de la cabeza y el tronco?",["Un único trayecto sinusoidal de 4,5 cm hacia el miembro que carga","Un doble trayecto sinusoidal de 4,5 a 5 cm por ciclo","Un trayecto rectilíneo, sin ninguna oscilación lateral"],["El desplazamiento lateral sigue una sinusoide única de unos 4,5 cm, orientada hacia el miembro en apoyo.","El doble trayecto caracteriza el desplazamiento vertical.","La oscilación lateral existe realmente."]],
  "118": ["¿Cuándo se activan los erectores del raquis torácico y lumbar?",["Únicamente durante la oscilación media del miembro","En el contacto inicial, con más intensidad en el lado contralateral","De forma continua, a baja intensidad, durante todo el ciclo"],["La oscilación media no es el momento de activación que se describe.","Los erectores se activan en el contacto inicial, y el lado contralateral trabaja con más intensidad para sostener el tronco.","La actividad continua de baja intensidad caracteriza al recto del abdomen."]],
  "119": ["¿Cuándo se activan los multífidos, los rotadores y el cuadrado lumbar?",["Únicamente en el despegue del antepié","Durante toda la fase de oscilación","En el choque de talón, de forma bilateral"],["El despegue del antepié no es el momento que se describe.","La oscilación no es el momento de activación que se describe.","Estos músculos se activan bilateralmente en el choque de talón, de forma asimétrica entre ambos lados."]],
  "120": ["¿Cómo se comporta el oblicuo externo durante la marcha?",["Poco activo en apoyo, con intensidad máxima en oscilación","Con intensidad máxima en apoyo, poco activo en oscilación","Con intensidad constante a lo largo de todo el ciclo de marcha"],["El oblicuo externo trabaja a baja intensidad durante el apoyo y alcanza su intensidad máxima durante la oscilación.","El perfil que se describe es el inverso.","La actividad continua de baja intensidad caracteriza al recto del abdomen."]],
  "121": ["¿Cómo se comporta el recto del abdomen durante la marcha?",["Con ráfagas de actividad únicamente en el choque de talón","Con una acción continua de baja intensidad","Con una actividad máxima durante la oscilación"],["La activación en el choque de talón corresponde a los multífidos y al cuadrado lumbar.","El recto del abdomen mantiene una actividad continua, de baja intensidad, durante todo el ciclo.","El pico en oscilación corresponde al oblicuo externo."]],
  "122": ["¿Qué factores influyen en la forma de caminar?",["El sexo, el peso y la talla del sujeto","La superficie, la pendiente y la temperatura","La edad, la cadencia y el calzado"],["Esos parámetros no son los factores establecidos.","Esas condiciones externas no son los factores establecidos.","Los tres factores que se señalan como influyentes en la forma de caminar son la edad, la cadencia y el calzado."]],
  "123": ["¿Qué característica marca la marcha del niño de 0 a 7 años?",["Una cadencia más alta y una oscilación más corta","Una cadencia más baja y una base de apoyo ampliada","Una zancada larga con contacto por el talón"],["El niño camina con una cadencia más alta, una oscilación y una duración de ciclo más cortas, pero una amplitud mayor.","Ese perfil corresponde a la persona mayor.","El niño apoya, al contrario, el pie entero."]],
  "124": ["¿Cómo aborda el suelo el niño menor de 7 años en el contacto inicial?",["Con el talón solo","Con el pie entero","Con el antepié solo"],["El contacto aislado con el talón es una adquisición más tardía.","En el niño, el contacto inicial se hace con el pie entero, y no solo con el talón.","El contacto con el antepié no es el patrón que se describe."]],
  "125": ["¿Qué particularidad de los miembros superiores se observa en el niño pequeño?",["Una amplitud de balanceo superior a la del adulto","Un balanceo sincrónico de ambos brazos hacia el mismo lado","La ausencia de movimiento recíproco de los brazos"],["El balanceo está ausente, no amplificado.","Ese patrón no es el que se describe.","El balanceo recíproco de los miembros superiores todavía no está instaurado en el niño pequeño."]],
  "126": ["¿Cómo evoluciona la marcha a partir de los 60 o 70 años?",["La zancada y la velocidad disminuyen, y la base de apoyo se amplía","La cadencia aumenta claramente y la zancada se alarga","La velocidad aumenta y la base de apoyo se estrecha"],["En la persona mayor, la amplitud y la velocidad de la zancada disminuyen, la cadencia baja y la base de soporte se amplía.","Ese perfil corresponde al niño.","La evolución que se describe es la inversa."]],
  "127": ["¿A qué parámetros está ligada la cadencia?",["A la anchura del paso y a la duración del doble apoyo bipodal","A la longitud de la zancada, a la amplitud de apoyo y al ángulo del paso","Al desplazamiento vertical y lateral del tronco al caminar"],["Esos parámetros no son los que se citan.","La cadencia se relaciona con la longitud de la zancada, la amplitud de apoyo y el ángulo del paso.","Esos desplazamientos corresponden a los mecanismos de optimización."]],
  "128": ["¿Qué distinción establece el temario a propósito del calzado?",["El desnivel talón-punta equivale a la altura de la suela","La altura de la suela determina por sí sola la amortiguación","El desnivel talón-punta no es la altura total de la suela"],["Ambos conceptos se distinguen precisamente.","La amortiguación no se reduce a la altura de la suela.","El temario distingue explícitamente el desnivel talón-punta de la altura total de la suela."]],
  "129": ["¿Qué significa el principio «prueba manual no es capacidad de marcha»?",["Un balance muscular normal no garantiza una marcha funcional","El balance muscular manual sustituye al análisis de la marcha","La marcha no depende de la fuerza muscular segmentaria"],["El balance analítico valora una fuerza aislada, mientras que la marcha pone en juego el control, la sensibilidad y la coordinación.","El análisis de la marcha sigue siendo indispensable más allá del balance.","La fuerza sigue siendo un determinante, pero no basta."]],
  "130": ["¿Cuál de estos mecanismos figura entre las causas de marcha patológica?",["El aumento de la cadencia espontánea","La alteración del control selectivo","La ampliación de la base de sustentación"],["La aceleración de la cadencia es una adaptación, no un mecanismo lesional.","Los mecanismos patológicos comprenden la debilidad, la pérdida de sensibilidad, el dolor, el control motor modificado y la alteración del control selectivo.","La ampliación de la base es una compensación, no una causa."]],
  "131": ["¿Cuántos grados tiene la graduación de la sensibilidad?",["Dos: presente o ausente","Cinco, como el balance muscular manual","Tres: ausente, alterada, normal"],["La graduación establecida incluye un grado intermedio.","La graduación en cinco niveles es la de la fuerza, no la de la sensibilidad.","La sensibilidad, a menudo descuidada, se gradúa en tres niveles: ausente, alterada o normal."]],
  "132": ["¿Qué consecuencia tiene la espasticidad sobre la marcha?",["La aparición de patrones locomotores primitivos","Una mejora de la disociación segmentaria","Una normalización progresiva de los rodillos"],["La espasticidad y la alteración del control selectivo hacen reaparecer patrones locomotores primitivos.","La espasticidad degrada, al contrario, la disociación.","Los rodillos quedan, al contrario, alterados."]],
  "133": ["¿Cómo se define una flexión plantar exagerada?",["La flexión plantar desaparece por completo del ciclo de marcha","La flexión plantar supera los valores normales en una o varias fases","La flexión plantar se limita solo al contacto inicial del pie con el suelo"],["La desaparición del patrón normal corresponde a la flexión dorsal exagerada.","La flexión plantar exagerada se define por superar los valores normales durante una o varias fases del ciclo de marcha.","La limitación a una sola fase no es la definición establecida."]],
  "134": ["¿Qué fase del ciclo deja indemne la flexión plantar exagerada?",["El apoyo medio","La oscilación media","La preoscilación"],["El apoyo medio está entre las fases afectadas.","La oscilación media está entre las fases afectadas.","La flexión plantar exagerada afecta a todas las fases del ciclo salvo la preoscilación."]],
  "135": ["¿Qué causa puede explicar una flexión plantar exagerada?",["Una debilidad de la musculatura pretibial","Una debilidad marcada del músculo tríceps sural","Un bloqueo del tobillo en posición neutra"],["Las causas comprenden la contractura o la espasticidad de los flexores plantares, la debilidad pretibial, la compensación de una debilidad del cuádriceps y el dolor.","La debilidad del tríceps sural provoca, al contrario, una flexión dorsal exagerada.","El bloqueo en posición neutra favorece una flexión dorsal exagerada."]],
  "136": ["¿Qué consecuencia funcional tiene la flexión plantar exagerada en la oscilación?",["Aumenta la absorción de los impactos en la rodilla","Dificulta la elevación y el avance del pie","Facilita el desarrollo del rodillo de talón"],["La absorción de los impactos queda, al contrario, comprometida.","La flexión plantar exagerada dificulta elevar el pie y después hacerlo avanzar durante la oscilación.","El rodillo de talón queda alterado, no facilitado."]],
  "137": ["¿Qué posición del tobillo corresponde a un contacto inicial normal?",["Una flexión plantar inferior a 15°","Una flexión plantar superior a 15°","Neutra, o en flexión plantar de 2 a 3°"],["Una flexión plantar inferior a 15° define el contacto bajo del talón.","Una flexión plantar superior a 15° conduce al contacto con el antepié.","El contacto inicial fisiológico se produce con el tobillo neutro o en flexión plantar de 2 a 3°."]],
  "138": ["¿A partir de qué flexión plantar se produce el contacto inicial con el antepié?",["Por encima de 15°","Por encima de 5°","Por encima de 30°"],["Una flexión plantar superior a 15° hace que el primer contacto recaiga en el antepié; por debajo, el contacto se produce en la base del talón.","Cinco grados de desviación se siguen considerando normales.","Treinta grados corresponde al grado máximo que alcanza una contractura en flexión plantar."]],
  "139": ["¿Cuál de estos mecanismos compensa una flexión plantar exagerada en la oscilación media?",["La flexión de la rodilla contraria","La circunducción","El descenso de la pelvis"],["La flexión de la rodilla contraria no figura entre las compensaciones que se describen.","Las cuatro compensaciones son la circunducción, el aumento de la flexión de cadera, el despegue precoz del talón contralateral y la inclinación contralateral del tronco.","El descenso de la pelvis homolateral es consecuencia de otra anomalía."]],
  "140": ["¿Cuál es la consecuencia de las compensaciones de una flexión plantar exagerada?",["Una sobrecarga del talón contralateral en el apoyo","Un aumento de la longitud del paso alcanzado","Un arrastre de los dedos y un riesgo de caída"],["La sobrecarga del talón opuesto no es la consecuencia que se describe.","La longitud del paso queda, al contrario, comprometida.","Cuando las compensaciones son insuficientes, el pie roza el suelo: de ello resulta un arrastre de los dedos y un riesgo de caída."]],
  "141": ["¿A qué fases afecta la flexión dorsal exagerada?",["A todas las fases del periodo de apoyo","A todas las fases salvo la preoscilación","Únicamente a las fases de oscilación"],["La flexión dorsal exagerada afecta al conjunto de las fases del periodo de apoyo.","Ese reparto es el de la flexión plantar exagerada.","En la oscilación solo cuenta la posición del tobillo en el contacto inicial."]],
  "142": ["¿Qué efecto tiene la flexión dorsal exagerada sobre el cuádriceps?",["Disminuye la demanda que se impone al cuádriceps","Aumenta la demanda que se impone al cuádriceps","No tiene ningún efecto sobre el cuádriceps"],["La demanda aumenta en lugar de disminuir.","Al acentuar el rodillo de talón y flexionar la rodilla, la flexión dorsal exagerada aumenta la demanda sobre el cuádriceps.","Se describe un efecto claro sobre el cuádriceps."]],
  "143": ["¿Qué consecuencia tiene la flexión dorsal exagerada sobre el miembro inferior?",["Alarga el miembro que carga y eleva la pelvis","Aumenta claramente la absorción de los impactos en la rodilla","Acorta la pierna y reduce el sostén de la pelvis"],["El efecto que se describe es el inverso.","La absorción de los impactos queda comprometida, no mejorada.","Al acortar funcionalmente el miembro, la flexión dorsal exagerada reduce el sostén que se aporta a la pelvis."]],
  "144": ["¿Qué causa explica una flexión dorsal exagerada?",["Una debilidad del músculo sóleo","Una contractura en flexión plantar","Una espasticidad de los flexores"],["Las causas establecidas son la debilidad del sóleo, el bloqueo del tobillo en posición neutra, la flexión de la rodilla en apoyo y el contacto aislado prolongado del talón.","La contractura en flexión plantar provoca la anomalía inversa.","La espasticidad de los flexores plantares provoca una flexión plantar exagerada."]],
  "145": ["¿Qué desviación angular se sigue considerando normal en el tobillo?",["Una desviación de 15°","Una desviación de 5°","Una desviación de 30°"],["Quince grados corresponde al umbral del contacto con el antepié.","Una desviación de 5° respecto a los valores esperados todavía puede considerarse normal.","Treinta grados corresponde a una contractura marcada en flexión plantar."]],
  "146": ["¿Qué refleja un paso brusco de la flexión plantar a la flexión dorsal al inicio del apoyo monopodal?",["Una debilidad moderada de los flexores plantares","Una hiperactividad de los músculos pretibiales","Una debilidad profunda de los flexores plantares"],["Una debilidad moderada da un aumento progresivo, y no brusco.","La hiperactividad pretibial interviene en el avance del miembro durante la oscilación.","El cambio brusco corresponde al primero de los dos patrones descritos y refleja una debilidad profunda de los flexores plantares."]],
  "147": ["¿Qué refleja un aumento progresivo de la flexión dorsal durante el apoyo medio y final?",["Una debilidad moderada de los flexores plantares","Una debilidad profunda de los flexores plantares","Una contractura marcada del músculo tríceps sural"],["El segundo patrón, progresivo, corresponde a una debilidad moderada de los flexores plantares.","Una debilidad profunda da un cambio brusco ya al inicio del apoyo monopodal.","Una contractura provocaría una flexión plantar exagerada."]],
  "148": ["¿Por qué es difícil detectar la flexión dorsal excesiva en el apoyo final?",["Porque el tobillo queda tapado por el pie contralateral","Porque dos acciones inclinan la tibia hacia delante","Porque la flexión dorsal desaparece en esa fase"],["No se describe ningún ocultamiento de ese tipo.","El despegue del talón y la flexión dorsal exagerada inclinan ambos la tibia: la anomalía solo se hace visible si el contacto del talón se prolonga.","La flexión dorsal persiste, al contrario, en esa fase."]],
  "149": ["¿Qué consecuencia tiene una flexión dorsal excesiva en la preoscilación?",["Una elevación compensadora de la pelvis opuesta","Un alargamiento del paso contralateral","Una caída acentuada de la pelvis homolateral"],["La elevación de la pelvis opuesta no es la consecuencia que se describe.","Este mecanismo no alarga el paso opuesto.","El acortamiento funcional del miembro reduce el sostén de la pelvis, de donde resulta una caída acentuada de la pelvis del mismo lado."]],
  "150": ["¿Cuál es la única relevancia clínica de una flexión dorsal exagerada durante la oscilación?",["La posición en la que estará el tobillo en el contacto inicial","La demanda que se impone al cuádriceps al final de la oscilación","El grado de absorción de los impactos en la rodilla"],["Durante las tres fases de oscilación, lo único que cuenta es la posición en la que se encontrará el tobillo en el momento del contacto inicial.","La demanda sobre el cuádriceps afecta a las fases de apoyo.","La absorción de los impactos interviene en la aceptación de la carga."]],
  "151": ["¿Cómo se define el contacto aislado prolongado del talón?",["El antepié toca el suelo antes que el talón, ya en el primer contacto con el suelo","El periodo exclusivo de apoyo del talón se prolonga más allá de la respuesta a la carga","El talón se despega del suelo antes del final de la fase de apoyo medio"],["Ese cuadro define el contacto tardío del talón.","En el contacto aislado prolongado del talón, el apoyo sigue recayendo únicamente en el talón más allá de la fase de respuesta a la carga.","Ese cuadro define el despegue precoz del talón."]],
  "152": ["¿Cuáles son las causas del contacto aislado prolongado del talón?",["Una debilidad del sóleo asociada a una flexión de la rodilla en apoyo","Una contractura marcada en flexión plantar del tobillo","Un dolor del antepié o una garra de los dedos espástica"],["Esa asociación explica una flexión dorsal exagerada.","La contractura en flexión plantar impediría el apoyo del talón.","Las dos causas establecidas son el dolor del antepié y la garra de los dedos asociada a la espasticidad."]],
  "153": ["¿Qué anomalía del pie aparece en el contacto inicial?",["El contacto con el antepié","El arrastre de los dedos","El contacto prolongado del talón"],["El contacto con el antepié es la anomalía propia del contacto inicial, igual que el contacto con el pie plano.","El arrastre de los dedos aparece en la fase de oscilación.","El contacto prolongado del talón afecta al apoyo final y a la preoscilación."]],
  "154": ["¿Qué consecuencia tiene el contacto con el antepié?",["Acentúa el rodillo de talón y la progresión de la tibia","Interrumpe el rodillo de talón y reduce la absorción de los impactos","Mejora la estabilidad durante el apoyo monopodal"],["El rodillo de talón queda suprimido, no acentuado.","Al suprimir el primer rodillo, dificulta el avance de la tibia y disminuye la absorción de los impactos en la rodilla.","Esta anomalía no mejora la estabilidad."]],
  "155": ["¿Qué causa puede explicar un contacto con el antepié?",["Una debilidad aislada del músculo sóleo durante el apoyo","Una garra de los dedos de origen espástico y doloroso","Una compensación de una desigualdad de longitud de los miembros"],["La debilidad del sóleo provoca una flexión dorsal exagerada.","La garra de los dedos explica un contacto aislado prolongado del talón.","Las causas comprenden la debilidad pretibial, la contractura en flexión plantar, el dolor del talón y la compensación de un miembro más corto."]],
  "156": ["¿Hasta qué amplitud puede llevar una contractura la flexión plantar en el contacto?",["Hasta 30°","Hasta 15°","Hasta 5°"],["Una fuerza insuficiente de los pretibiales o una contractura puede conducir a una flexión plantar excesiva que alcance los 30°.","Quince grados es el umbral por encima del cual el contacto se produce con el antepié.","Cinco grados corresponde a la desviación que todavía se considera normal."]],
  "157": ["¿Cómo se define el contacto tardío del talón?",["El talón permanece como único apoyo más allá de la respuesta a la carga","El antepié entra en contacto con el suelo antes que el talón","El talón se despega antes del final del apoyo medio"],["Esa descripción es la del contacto aislado prolongado del talón.","En el contacto tardío del talón, es el antepié el que toca el suelo primero.","Esa descripción es la del despegue precoz del talón."]],
  "158": ["¿A qué fases afecta el contacto tardío del talón?",["Al apoyo final y a la preoscilación","A las fases de oscilación","Al apoyo inicial y al apoyo medio"],["Esas dos fases corresponden al contacto prolongado del talón.","La oscilación se ve afectada por el arrastre de los dedos y el impulso contralateral.","El contacto tardío del talón altera el apoyo inicial y el apoyo medio."]],
  "159": ["¿Qué causa explica un contacto tardío del talón?",["Una contractura o una espasticidad en flexión plantar que cede con la carga","Una debilidad profunda de los flexores plantares del tobillo afectado","Un dolor localizado en el antepié y en las cabezas metatarsianas"],["El contacto tardío del talón resulta de una contractura o de una espasticidad en flexión plantar que se atenúa al cargar el peso.","Esa debilidad provoca una flexión dorsal exagerada.","El dolor del antepié explica el contacto aislado prolongado del talón."]],
  "160": ["¿A qué fases afecta el contacto prolongado del talón?",["Al apoyo inicial y al apoyo medio","Al apoyo final y a la preoscilación","Únicamente al contacto inicial"],["Esas fases corresponden al contacto tardío del talón.","El contacto prolongado del talón, o retraso del despegue, afecta al apoyo final y a la preoscilación.","El contacto inicial se ve afectado por el contacto con el antepié y por el pie plano."]],
  "161": ["¿Durante qué periodo aparecen el arrastre de los dedos y el impulso contralateral?",["Durante el apoyo medio","Durante el contacto inicial","Durante la oscilación"],["El apoyo medio se ve afectado por otras anomalías del pie.","El contacto inicial se ve afectado por el contacto con el antepié y por el pie plano.","El arrastre de los dedos y el impulso contralateral son dos anomalías de la fase de oscilación."]],
  "162": ["¿En qué fase se produce la caída brusca del pie?",["En el apoyo inicial","En el contacto inicial","En el apoyo final"],["La caída brusca del pie, o chasquido, se produce durante el apoyo inicial, en el momento de la respuesta a la carga.","El contacto inicial se ve afectado por el contacto con el antepié o por el pie plano.","El apoyo final se ve afectado por el contacto prolongado del talón."]],
  "163": ["¿A qué fases altera el despegue precoz del talón?",["Únicamente al apoyo final y a la preoscilación","Al contacto inicial, al apoyo inicial y al apoyo medio","A las tres fases del periodo de oscilación"],["Esas dos fases corresponden al contacto prolongado del talón.","El despegue precoz del talón altera el contacto inicial, el apoyo inicial y el apoyo medio.","La oscilación corresponde a otras anomalías."]],
  "164": ["¿Cómo se define el contacto con el pie plano?",["El antepié toca el suelo claramente antes que el talón","El talón toca el suelo y el antepié queda muy cerca","El talón y el antepié tocan el suelo simultáneamente"],["Ese cuadro corresponde al contacto tardío del talón.","Esa descripción corresponde al contacto bajo del talón.","En el contacto plano, el talón y el antepié abordan el suelo al mismo tiempo: desaparece el periodo de apoyo exclusivo del talón."]],
  "165": ["¿Qué causa explica un contacto con el pie plano?",["Una compensación de una debilidad del cuádriceps","Una debilidad aislada de los músculos pretibiales","Un dolor localizado en el antepié"],["Cualquier alteración que favorezca una flexión excesiva de la rodilla, y en particular la compensación de un cuádriceps débil, conduce al contacto plano.","La debilidad pretibial provoca más bien una caída brusca del pie.","El dolor del antepié explica un contacto aislado prolongado del talón."]],
  "166": ["¿Cómo se define la caída brusca del pie?",["Un despegue del talón que se produce demasiado pronto en el apoyo","Una flexión plantar incontrolada tras el contacto del talón","Un contacto simultáneo del talón y del antepié"],["Ese cuadro corresponde al despegue precoz del talón.","El pie cae de forma incontrolable después del primer contacto, a menudo con un chasquido audible.","Ese cuadro corresponde al contacto con el pie plano."]],
  "167": ["¿Cuál es la causa de la caída brusca del pie?",["Una debilidad del tríceps sural y de los flexores plantares","Una espasticidad marcada de los músculos flexores plantares","Una debilidad pretibial, en particular del tibial anterior"],["La debilidad del tríceps sural repercute en la propulsión, no en el descenso del pie.","La espasticidad bloquearía el tobillo, en lugar de dejar caer el pie.","El tibial anterior ya no frena el descenso del antepié tras el contacto del talón."]],
  "168": ["¿Cómo se caracteriza el contacto bajo del talón?",["El talón toca el suelo, pero el antepié queda muy cerca de él","El antepié es el primer punto de contacto con el suelo","El talón permanece como único apoyo más allá de la respuesta a la carga"],["El talón sí establece el contacto inicial, pero el antepié queda muy cerca del suelo: el tobillo está en flexión plantar de unos 10° con una rodilla normal.","Ese cuadro corresponde al contacto con el antepié.","Ese cuadro corresponde al contacto aislado prolongado del talón."]],
  "169": ["¿Qué causa puede producir un tiempo de apoyo aislado del talón acortado?",["Una debilidad del sóleo durante toda la fase de apoyo monopodal","Una contractura que coloque el tobillo en flexión plantar de menos de 15°","Un dolor del antepié en el momento del despegue del pie"],["La debilidad del sóleo provoca una flexión dorsal exagerada.","Cualquier alteración que provoque una flexión plantar excesiva, pero inferior a 15°, acorta el periodo de apoyo del talón.","El dolor del antepié prolonga, al contrario, el apoyo del talón."]],
  "170": ["¿Qué consecuencia tiene el despegue precoz del talón?",["Interrumpe el rodillo del antepié en el despegue","Suprime la absorción de los impactos en la rodilla durante la oscilación","Interrumpe el rodillo de talón y dificulta el del tobillo"],["El rodillo del antepié se ve alterado por el contacto prolongado del talón.","La absorción de los impactos interviene en la aceptación de la carga, no en la oscilación.","Al elevar el talón demasiado pronto, suprime el primer rodillo e interfiere con el rodillo de tobillo."]],
  "171": ["¿Qué causa puede explicar un despegue precoz del talón?",["Un aumento de la actividad de los flexores plantares","Una debilidad del tríceps sural durante la fase de apoyo final","Una hiperactividad marcada de los músculos pretibiales de la pierna"],["Las causas comprenden la hiperactividad de los flexores plantares, el dolor del talón, la compensación de un miembro corto y una flexión excesiva de la rodilla.","La debilidad del tríceps sural retrasa, al contrario, el despegue del talón.","La hiperactividad pretibial favorece una flexión dorsal exagerada."]],
  "172": ["¿Qué consecuencias tiene el contacto prolongado del talón?",["Interrumpe el rodillo de talón y la progresión de la tibia","Interrumpe el rodillo del antepié y acorta el paso opuesto","Aumenta la flexión de la rodilla durante la preoscilación"],["El rodillo de talón se ve alterado por el contacto con el antepié.","Al no elevarse el talón, se suprime el tercer rodillo, se reduce la progresión y se acorta el paso contralateral.","La flexión de la rodilla queda, al contrario, limitada en la preoscilación."]],
  "173": ["¿Qué causa explica un contacto prolongado del talón?",["Una hiperactividad de los flexores plantares","Una debilidad de la musculatura pretibial","Una debilidad del tríceps sural"],["La hiperactividad de los flexores plantares provoca un despegue precoz.","La debilidad pretibial provoca una caída brusca del pie.","Las causas comprenden la debilidad del tríceps sural, el dolor del antepié y la hiperextensión de la rodilla."]],
  "174": ["¿Cómo se define la inversión exagerada del pie?",["Una inversión del calcáneo o del antepié que supera la posición neutra","Una eversión del calcáneo o del antepié que supera la posición neutra","Una flexión plantar que supera los valores normales de la fase"],["La inversión exagerada supera la posición neutra durante una fase determinada; afecta a todas las fases del ciclo.","Ese cuadro define la eversión exagerada.","Ese cuadro define la flexión plantar exagerada."]],
  "175": ["¿Qué consecuencia tiene la inversión exagerada en la recepción de la carga?",["El mediopié se desbloquea y pierde toda su rigidez de apoyo","La rigidez del mediopié limita la absorción del impacto","El rodillo de talón queda totalmente suprimido"],["El desbloqueo del mediopié caracteriza la eversión exagerada.","La rigidez asociada del mediopié impide que el pie amortigüe correctamente el impacto.","La supresión del rodillo de talón corresponde a las anomalías de contacto."]],
  "176": ["¿Cuál es la consecuencia principal de la inversión exagerada durante la oscilación?",["El aumento de la carga rotatoria en la rodilla y el tobillo","El alargamiento relativo del miembro contralateral durante el apoyo","La dificultad para despegar el pie del suelo, por caída del borde lateral"],["El aumento de la carga rotatoria caracteriza la eversión exagerada.","El alargamiento relativo del miembro opuesto corresponde a las anomalías pélvicas.","La caída del borde lateral del pie dificulta su despegue durante la oscilación."]],
  "177": ["¿Qué causa explica una inversión exagerada?",["Una hiperactividad de los músculos inversores","Una debilidad de la musculatura inversora","Una hipertonía de los músculos peroneos"],["Las causas comprenden la hiperactividad de los inversores, la contractura en equinovaro, el patrón espástico y las deformidades esqueléticas.","La debilidad de los inversores provoca, al contrario, una eversión exagerada.","La hipertonía peronea favorece la eversión exagerada."]],
  "178": ["¿Qué efecto tiene la eversión exagerada durante el apoyo monopodal?",["Rigidiza el mediopié y bloquea por completo la absorción de los impactos","Desbloquea el mediopié e impide la rigidez necesaria para el despegue","Suprime el rodillo de talón ya en el contacto inicial del pie"],["La rigidez del mediopié caracteriza la inversión exagerada.","El desbloqueo del mediopié priva al antepié de la rigidez indispensable para el despegue del talón y la progresión.","El rodillo de talón corresponde a las anomalías de contacto."]],
  "179": ["¿Para qué puede servir la eversión excesiva cuando el tobillo está limitado?",["Como compensación para ganar flexión plantar en el despegue","Como mecanismo de absorción de los impactos en el contacto inicial","Como compensación para ganar flexión dorsal durante el apoyo"],["No es esa la compensación que se describe.","La eversión excesiva no mejora la absorción de los impactos.","Ante una movilidad de tobillo limitada, la eversión excesiva sirve de mecanismo compensador para aumentar la amplitud de flexión dorsal."]],
  "180": ["¿Qué causa explica una eversión exagerada?",["Una debilidad de la musculatura inversora","Una contractura en equinovaro del pie","Una hiperactividad de los músculos inversores"],["Las causas comprenden la debilidad de los inversores, la hipertonía peronea, un arco plantar bajo y la deformidad en valgo.","La contractura en equinovaro provoca una inversión exagerada.","La hiperactividad de los inversores provoca una inversión exagerada."]],
  "181": ["¿Cuáles son los dos mecanismos de una extensión exagerada de la rodilla?",["La flexión inapropiada y el wobble","El empuje extensor y la hiperextensión","El valgo y el varo frontales"],["Esas dos anomalías son distintas de la extensión exagerada.","La extensión exagerada de la rodilla procede o de un empuje extensor, o de una hiperextensión, también llamada recurvatum.","El valgo y el varo son las anomalías del plano frontal."]],
  "182": ["¿Cómo se define el empuje extensor de la rodilla?",["Una colocación de la rodilla por detrás de la posición neutra","Una alternancia rápida de flexión y extensión","Un movimiento enérgico de la rodilla hacia la extensión"],["Esa colocación define la hiperextensión, o recurvatum.","Esa alternancia define la inestabilidad oscilatoria.","El empuje extensor es un movimiento vivo de la rodilla hacia la extensión, que se observa en el contacto inicial y durante el apoyo inicial y medio."]],
  "183": ["¿Cuál es el interés funcional de un empuje extensor de la rodilla?",["Reduce la solicitación de un cuádriceps débil","Mejora la absorción de los impactos en el apoyo inicial","Facilita el despegue del pie en la oscilación"],["Al bloquear la rodilla, el empuje extensor descarga un cuádriceps deficiente, a costa de la absorción de los impactos.","La absorción de los impactos queda, al contrario, disminuida.","El despegue del pie no es lo que está en juego en esta anomalía."]],
  "184": ["¿Cómo se denomina la hiperextensión de la rodilla?",["El wobble de la rodilla","El recurvatum","El genu valgum"],["El wobble designa la inestabilidad oscilatoria de la rodilla.","La hiperextensión coloca la rodilla por detrás de la posición anatómica neutra: es el recurvatum.","El valgo es una anomalía del plano frontal."]],
  "185": ["¿Qué causa explica una hiperextensión de la rodilla en el apoyo medio?",["Una debilidad aislada de los isquiotibiales del lado afectado, en apoyo","Una contractura en flexión de la rodilla y de la cadera del lado afectado","Una debilidad combinada del cuádriceps y de los flexores plantares"],["La insuficiencia de los isquiotibiales conduce a una extensión inapropiada.","La contractura en flexión impediría precisamente la hiperextensión.","En el apoyo medio, la hiperextensión resulta de la asociación de una debilidad del cuádriceps y de los flexores plantares."]],
  "186": ["¿Cómo se define una flexión inapropiada de la rodilla?",["Una flexión de la rodilla inferior a la normal para la fase considerada","Una flexión de la rodilla superior a la normal para la fase considerada","Una extensión de la rodilla inferior a la normal para la fase"],["La flexión inapropiada corresponde a un déficit de flexión en una de las cuatro fases en las que la flexión es la norma.","Esa definición es la de la flexión exagerada.","Esa definición es la de la extensión inapropiada."]],
  "187": ["¿Qué consecuencia tiene una flexión inapropiada de la rodilla en la oscilación?",["Aumenta claramente la demanda que se impone al cuádriceps","Dificulta la elevación del pie y favorece su roce con el suelo","Acorta claramente la longitud del paso contralateral"],["La demanda sobre el cuádriceps queda, al contrario, reducida.","El déficit de flexión en la preoscilación y en la oscilación dificulta la elevación del pie y favorece su arrastre.","El acortamiento del paso opuesto corresponde a la extensión inapropiada."]],
  "188": ["¿Qué causa explica una flexión inapropiada de la rodilla?",["Una contractura en flexión de la rodilla","Una debilidad del sóleo en el apoyo medio","Una contractura en extensión de la rodilla"],["La contractura en flexión provoca una extensión inapropiada.","La debilidad del sóleo provoca una extensión inapropiada.","Las causas comprenden la debilidad del cuádriceps, la espasticidad, el dolor articular, la contractura en extensión y las sinergias primitivas."]],
  "189": ["¿Cómo se define una extensión inapropiada de la rodilla?",["Una extensión de la rodilla inferior a la normal para la fase considerada","Una extensión de la rodilla superior a la normal para la fase considerada","Una flexión de la rodilla inferior a la normal para la fase considerada"],["La extensión inapropiada es un déficit de extensión en una de las cuatro fases en las que la extensión es la norma.","Esa definición es la de la extensión exagerada.","Esa definición es la de la flexión inapropiada."]],
  "190": ["¿Qué consecuencia tiene una extensión inapropiada de la rodilla en el apoyo medio y final?",["Favorece el roce del pie con el suelo","Acorta el paso contralateral","Reduce la demanda que se impone al cuádriceps"],["El arrastre del pie corresponde a la flexión inapropiada.","El déficit de extensión en el apoyo medio y final acorta el paso del lado opuesto.","La demanda sobre el cuádriceps queda, al contrario, aumentada."]],
  "191": ["¿Qué causa explica una extensión inapropiada de la rodilla?",["Una contractura en extensión de la rodilla con sinergias primitivas","Una espasticidad del cuádriceps y de los flexores plantares","Una contractura en flexión de la rodilla o un derrame articular"],["La contractura en extensión provoca una flexión inapropiada.","La espasticidad del cuádriceps favorece la extensión exagerada.","Las causas comprenden la insuficiencia de los isquiotibiales, la flexión plantar exagerada, el dolor, la contractura en flexión, el derrame y la debilidad del sóleo."]],
  "192": ["¿Qué consecuencia tiene una flexión exagerada de la rodilla en el apoyo inicial?",["La amortiguación pierde eficacia y aumenta la demanda del cuádriceps","La amortiguación mejora y disminuye la demanda del cuádriceps","El rodillo de talón queda totalmente suprimido"],["Una flexión excesiva degrada la amortiguación y aumenta la solicitación del cuádriceps.","El efecto que se describe es exactamente el inverso.","La supresión del rodillo de talón corresponde a las anomalías de contacto."]],
  "193": ["¿Cómo se define la inestabilidad oscilatoria de la rodilla?",["Una colocación permanente de la rodilla en recurvatum durante el apoyo","Flexiones y extensiones rápidas y alternas dentro de una misma fase","Un único movimiento enérgico de la rodilla hacia la extensión completa"],["El recurvatum es una posición fija, no una alternancia.","El wobble es una alternancia rápida de flexión y extensión que aparece dentro de una sola fase del ciclo.","Ese movimiento único define el empuje extensor."]],
  "194": ["¿Qué anomalías de la rodilla pertenecen al plano frontal?",["La extensión y la flexión exageradas","El wobble y el recurvatum","El valgo y el varo de la rodilla"],["Los defectos de amplitud en flexoextensión pertenecen al plano sagital.","El wobble y el recurvatum pertenecen al plano sagital.","En el plano frontal, las anomalías de la rodilla son el valgo y el varo; las demás pertenecen al plano sagital."]],
  "195": ["¿Cómo compensa el tronco una contractura moderada en flexión de cadera?",["Con un aumento de la lordosis lumbar","Con una inclinación contralateral del tronco","Con una retroversión marcada de la pelvis"],["Una contractura de 15° se compensa con facilidad mediante una hiperlordosis lumbar, que vuelve a alinear el vector corporal sobre el pie de apoyo.","La inclinación contralateral compensa un déficit de flexión de cadera o de rodilla en la oscilación.","La retroversión compensa una debilidad de los flexores de cadera."]],
  "196": ["¿Por qué compensa mal el adulto una contractura grave en flexión de cadera?",["Porque sus extensores de cadera son demasiado débiles","Porque su movilidad vertebral es insuficiente","Porque su base de sustentación es demasiado estrecha"],["La debilidad muscular no es el límite que se invoca.","Al faltarle movilidad raquídea suficiente, el centro de gravedad del adulto permanece por delante de la zona de apoyo del pie.","La base de apoyo no está implicada en esta limitación."]],
  "197": ["¿Por qué compensa mejor el niño una contractura grave en flexión de cadera?",["Porque su centro de gravedad se sitúa mucho más abajo que en el adulto","Porque sus flexores de cadera son mucho más flexibles","Porque la maleabilidad del crecimiento permite desarrollar la lordosis necesaria"],["La altura del centro de gravedad no es el argumento establecido.","Es la columna, y no la cadera, la que aporta la compensación.","La flexibilidad raquídea del niño en crecimiento permite la lordosis compensadora que el adulto ya no puede producir."]],
  "198": ["¿Para qué sirve una flexión exagerada de cadera durante la oscilación media?",["Para facilitar el despegue del pie cuando la flexión plantar es excesiva","Para reducir la solicitación que se impone a los extensores de cadera en apoyo","Para alargar el paso del miembro contralateral durante el apoyo"],["La flexión de cadera aumentada sirve a menudo para despegar el pie cuando el tobillo permanece en flexión plantar excesiva.","Durante el apoyo, la flexión excesiva aumenta, al contrario, esa solicitación.","El alargamiento del paso opuesto no es el efecto que se describe."]],
  "199": ["¿Cuál es el efecto de una flexión exagerada de cadera durante la fase de apoyo?",["Descarga claramente los extensores de cadera y el cuádriceps","Aumenta la solicitación de los extensores de cadera y del cuádriceps","Suprime el rodillo del antepié en el momento del despegue"],["El efecto que se describe es el inverso.","Salvo compensación por el tronco, la flexión excesiva aumenta la demanda sobre los extensores de cadera y sobre el cuádriceps.","El rodillo del antepié no está implicado."]],
  "200": ["¿Qué consecuencia tiene una flexión inapropiada de cadera en la oscilación?",["Aumenta la longitud de la zancada del miembro","Mejora la absorción de los impactos en la rodilla","Dificulta el avance del miembro y acorta la zancada"],["La zancada queda, al contrario, acortada.","La absorción de los impactos no está implicada.","El déficit de flexión de cadera frena el avance del miembro, acorta la zancada y puede dificultar la elevación del pie."]],
  "201": ["¿Qué causa explica una flexión inapropiada de cadera?",["Una espasticidad o una hipertonía de los isquiotibiales","Una contractura en flexión de la cadera del lado afectado","Una espasticidad marcada de los flexores de la cadera"],["Las causas comprenden la debilidad de los flexores de cadera, la espasticidad de los isquiotibiales y la reducción voluntaria de la demanda sobre los extensores.","La contractura en flexión provoca una flexión exagerada.","La espasticidad de los flexores favorece la flexión exagerada."]],
  "202": ["¿Qué consecuencia tiene una aducción exagerada de cadera durante el apoyo?",["Aumenta la longitud relativa del miembro","Compromete la estabilidad del miembro que carga","Mejora la alineación del centro de gravedad"],["El alargamiento relativo corresponde a las anomalías pélvicas.","Durante el apoyo, la aducción exagerada interfiere con la estabilidad; en la oscilación, dificulta el despegue del pie y el avance del miembro.","Esta anomalía no mejora la alineación."]],
  "203": ["¿Qué causa explica una aducción exagerada de cadera?",["Una contractura de los aductores del lado opuesto al miembro estudiado","Una debilidad de los aductores del mismo lado que el miembro estudiado","Una debilidad de los abductores del mismo lado con caída pélvica opuesta"],["Lo que se cita es la contractura de los abductores contralaterales.","La debilidad de los aductores homolaterales explica una caída pélvica homolateral.","Las causas comprenden la debilidad de los abductores homolaterales, la sustitución de unos flexores débiles por los aductores, la espasticidad de los aductores y la dismetría."]],
  "204": ["¿Qué referencias óseas sirven para medir la inclinación de la pelvis en el plano sagital?",["Las espinas ilíacas anterosuperior y posterosuperior","Las crestas ilíacas derecha e izquierda de la pelvis ósea","La sínfisis del pubis y el promontorio del sacro, por delante"],["La línea que une la espina ilíaca posterosuperior con la anterosuperior sirve de referencia para la inclinación sagital.","Las crestas ilíacas sirven para valorar las caídas pélvicas en el plano frontal.","Esas referencias delimitan el estrecho superior de la pelvis."]],
  "205": ["¿Cuál es la inclinación anterior normal de la pelvis durante la marcha?",["Unos 25° respecto a la horizontal","Unos 10° respecto a la horizontal","Una inclinación nula, estrictamente horizontal"],["Ese valor es muy superior a la referencia.","En una marcha normal, la línea que une ambas espinas ilíacas se inclina unos 10° sobre la horizontal.","Sí existe una inclinación anterior fisiológica."]],
  "206": ["¿Cómo se define una anteversión pélvica exagerada?",["La sínfisis del pubis se orienta hacia arriba más allá de lo normal","Una cresta ilíaca se sitúa más abajo que la cresta opuesta","La sínfisis del pubis se orienta hacia abajo más allá de la postura normal"],["Esa descripción es la de la retroversión exagerada.","Esa descripción es la de una caída pélvica.","La anteversión exagerada bascula la pelvis de modo que la sínfisis del pubis mira hacia abajo, más allá de los 10° fisiológicos."]],
  "207": ["¿Qué riesgo entraña una anteversión pélvica excesiva?",["Dolores lumbares, cuando se acompaña de una hiperlordosis","Una inestabilidad de la rodilla durante toda la fase de apoyo monopodal","Una supresión del rodillo del antepié en el despegue"],["Asociada a una lordosis lumbar aumentada, la anteversión excesiva puede provocar lumbalgias.","La inestabilidad de la rodilla corresponde a otras anomalías.","El rodillo del antepié no está implicado."]],
  "208": ["¿Qué causa explica una anteversión pélvica exagerada?",["Un acortamiento marcado de los isquiotibiales","Una debilidad de los extensores de cadera o de los abdominales","Una debilidad clara de los flexores de cadera"],["El acortamiento de los isquiotibiales produce una retroversión.","Las causas comprenden la debilidad de los extensores de cadera, la espasticidad o la contractura de los flexores, la debilidad abdominal y la contractura del tensor de la fascia lata.","La debilidad de los flexores favorece la retroversión."]],
  "209": ["¿De qué es signo la retroversión pélvica exagerada?",["De una contractura de los flexores de cadera","De una debilidad de los abductores de cadera","De un acortamiento de los isquiotibiales"],["La contractura de los flexores provoca una anteversión.","La debilidad de los abductores se traduce en una caída pélvica.","La báscula posterior de la pelvis indica un acortamiento de los isquiotibiales, o compensa una debilidad de los flexores de cadera."]],
  "210": ["¿Para qué sirve la elevación pélvica durante la marcha?",["Para facilitar la elevación del pie durante la oscilación","Para estabilizar el miembro que carga durante el apoyo","Para alargar el paso del miembro contralateral"],["La elevación de una hemipelvis ayuda al despegue del pie en la oscilación, pero aumenta el coste energético.","La estabilidad del apoyo no es el objeto de esta compensación.","Este mecanismo no alarga el paso opuesto."]],
  "211": ["¿En qué fases se produce la elevación pélvica?",["Durante el apoyo inicial y el apoyo medio","Durante las tres fases de oscilación","Durante el apoyo final y la preoscilación"],["Esas fases corresponden a la caída pélvica contralateral.","La elevación pélvica se observa en la oscilación inicial, media y final.","Esas fases no son las que se describen."]],
  "212": ["¿Cómo se define una caída pélvica contralateral?",["La cresta ilíaca del lado estudiado desciende por debajo de la del lado opuesto","Las dos crestas ilíacas se elevan simultáneamente por encima de la neutra","La cresta ilíaca opuesta desciende por debajo de la cresta del lado estudiado"],["Esa descripción es la de la caída homolateral.","No se describe ninguna elevación bilateral.","En la caída contralateral, la cresta ilíaca del lado opuesto se sitúa más abajo que la del lado de referencia."]],
  "213": ["¿Qué causa explica una caída pélvica contralateral?",["Una debilidad de los abductores de cadera del lado estudiado","Una debilidad de los aductores de cadera del lado estudiado","Un acortamiento marcado de los músculos isquiotibiales"],["Las causas comprenden la debilidad de los abductores homolaterales, la contractura o la espasticidad de los abductores opuestos y una dismetría.","La debilidad de los aductores homolaterales provoca una caída homolateral.","El acortamiento de los isquiotibiales provoca una retroversión."]],
  "214": ["¿Qué consecuencia tiene una caída pélvica homolateral durante la oscilación?",["Acorta claramente el miembro de referencia","Aumenta la longitud relativa del miembro de referencia","Estabiliza más el miembro que carga"],["El efecto que se describe es el inverso.","Al descender su propia hemipelvis, el sujeto alarga relativamente el miembro estudiado, lo que dificulta su despegue.","La caída homolateral no estabiliza el apoyo."]],
  "215": ["¿Cuál es el interés de una inclinación posterior del tronco?",["Mejora la estabilidad de la rodilla durante el apoyo","Reduce la demanda sobre los abductores de cadera","Suple unos extensores de cadera débiles"],["La estabilidad de la rodilla la mejora la inclinación anterior.","La descarga de los abductores corresponde a la inclinación homolateral.","Al llevar el centro de gravedad por detrás de la cadera, la inclinación posterior sustituye a unos extensores de cadera deficientes."]],
  "216": ["¿Hacia dónde desplaza el centro de gravedad la inclinación posterior del tronco?",["Por detrás de la articulación de la cadera","Por delante de la articulación de la rodilla","Por encima del pie de apoyo, a plomo del talón"],["El centro de gravedad pasa por detrás de la cadera, lo que crea un momento extensor pasivo.","El desplazamiento por delante de la rodilla resulta de la inclinación anterior.","Esa recolocación no es la que se describe."]],
  "217": ["¿Qué causa explica una inclinación anterior del tronco?",["Una debilidad de los abductores de cadera","Una debilidad del cuádriceps","Un acortamiento de los isquiotibiales"],["La debilidad de los abductores provoca una inclinación homolateral.","Las causas comprenden la contractura o la espasticidad de los flexores plantares, la debilidad del cuádriceps o de los extensores de cadera y el uso de un producto de apoyo.","El acortamiento de los isquiotibiales produce una retroversión pélvica."]],
  "218": ["¿Cómo compensa la inclinación anterior del tronco una debilidad del cuádriceps?",["Desplazando el vector de carga por detrás de la rodilla","Acercando el centro de gravedad al miembro que carga","Desplazando el vector de carga por delante de la rodilla"],["Un vector posterior aumentaría la demanda sobre el cuádriceps.","Ese acercamiento lateral es el efecto de la inclinación homolateral.","El vector que pasa por delante de la rodilla crea un momento extensor pasivo, siempre que el tobillo esté estabilizado."]],
  "219": ["¿Cuál es el coste de una inclinación anterior del tronco?",["Aumenta el coste energético y la demanda sobre los extensores","Disminuye la demanda sobre los extensores del tronco","Desestabiliza sistemáticamente la rodilla durante el apoyo"],["La inclinación anterior aumenta el gasto energético y la solicitación de los extensores de cadera y del tronco.","La demanda aumenta, al contrario.","Puede, al contrario, mejorar la estabilidad de la rodilla."]],
  "220": ["¿Cuál es el efecto de una inclinación homolateral del tronco durante el apoyo?",["Aumenta la demanda sobre los abductores de cadera del mismo lado","Reduce la demanda sobre los abductores de cadera del mismo lado","Suple unos extensores de cadera que se han vuelto débiles"],["El efecto que se describe es el inverso.","Al acercar el centro de gravedad al miembro que carga, la inclinación homolateral descarga unos abductores débiles.","La suplencia de los extensores corresponde a la inclinación posterior."]],
  "221": ["¿Cuál es el inconveniente de una inclinación homolateral del tronco?",["Suprime el rodillo de talón en el momento del contacto inicial","Acorta sistemáticamente el paso del lado homolateral","Aumenta el coste energético y perjudica el equilibrio en la oscilación"],["El rodillo de talón no está implicado.","El acortamiento del paso no es el inconveniente que se describe.","Frena el impulso hacia delante, cuesta energía y compromete el equilibrio durante la oscilación."]],
  "222": ["¿Qué causa explica una inclinación homolateral del tronco durante el apoyo?",["Una debilidad de los abductores de cadera del mismo lado","Una alteración de la imagen corporal del sujeto","Una debilidad de los extensores de la cadera"],["Las causas en apoyo comprenden la debilidad de los abductores homolaterales, la contractura de los aductores del mismo lado y una cintilla iliotibial tensa.","La alteración de la imagen corporal interviene durante la oscilación.","La debilidad de los extensores provoca una inclinación posterior."]],
  "223": ["¿Qué supone una inclinación contralateral del tronco durante el apoyo?",["Es una postura que descarga los abductores","Es una postura claramente inestable","Es una postura que estabiliza la rodilla"],["La descarga de los abductores del lado que carga corresponde a la inclinación homolateral.","Durante el apoyo, la inclinación hacia el lado opuesto coloca al sujeto en una posición inestable.","La estabilidad de la rodilla no está en juego aquí."]],
  "224": ["¿Para qué sirve una inclinación contralateral del tronco durante la oscilación?",["Para reducir la demanda sobre los abductores del miembro que carga","Para mejorar la absorción de los impactos en el contacto inicial","Para compensar una flexión insuficiente de cadera o de rodilla"],["La descarga del miembro que carga corresponde a la inclinación homolateral.","La absorción de los impactos no está implicada.","Sirve de maniobra compensadora ante un déficit de flexión de cadera o de rodilla, y descarga los abductores del miembro opuesto."]]
});
